NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Exodus'

CHAPTERS = {
    1: {
        1: 'Torej to so imena Izraelovih otrok, ki so prišli v Egipt. Z Jakobom je prišel vsak mož in njegova družina.',
        2: 'Ruben, Simeon, Lévi in Juda,',
        3: 'Isahár, Zábulon in Benjamin,',
        4: 'Dan in Neftáli, Gad in Aser.',
        5: 'Vseh duš, ki so prišle iz Jakobovih ledij, je bilo sedemdeset duš, kajti Jožef je bil že v Egiptu.',
        6: 'Jožef je umrl in vsi njegovi bratje in ves ta rod.',
        7: 'Izraelovi otroci pa so bili rodovitni in obilno narasli in se namnožili in postali silno mogočni in dežela je bila napolnjena z njimi.',
        8: 'Sedaj je tam vstal nov kralj nad Egiptom, ki ni poznal Jožefa.',
        9: 'Svojemu ljudstvu je rekel: »Glejte, ljudstva Izraelovih otrok je več in mogočnejši so, kakor smo mi.',
        10: 'Pridite, modro ravnajmo z njimi, da se ne bi namnožili in se pripeti, ko izpade kakšna vojna, da se pridružijo tudi našim sovražnikom in se borijo zoper nas in tako jih napodimo iz dežele.«',
        11: 'Zato so nadnje postavili preddelavce, da jih stiskajo z njihovimi bremeni. In za faraona so gradili zakladni mesti Pitóm in Ramesés.',
        12: 'Toda bolj so jih stiskali, bolj so se množili in rastli. In bili so užaloščeni zaradi Izraelovih otrok.',
        13: 'Egipčani so s krutostjo Izraelove otroke prisilili, da so služili.',
        14: 'Njihova življenja so zagrenili s trdim suženjstvom, z malto, z opeko in z vsemi vrstami službe na polju. Vse njihove službe, s katerimi so jih pripravili, da jim služijo, so bile s krutostjo.',
        15: 'Egiptovski kralj je spregovoril hebrejskima babicama, katerih prvi je bilo ime Šifra, ime drugi pa Pua',
        16: '§ in rekel: »Ko hebrejskim ženam opravljata službo babice in jih vidita na stolčkih; če je sin, potem ga ubijta, toda če je hči, potem naj živi.«',
        17: 'Toda babici sta se bali Boga in nista delali, kakor jima je egiptovski kralj ukazal, temveč sta fantke rešili žive.',
        18: 'Egiptovski kralj je dal poklicati babici in jima rekel: »Zakaj sta storili to stvar in fantke rešili žive?«',
        19: 'Babici sta faraonu rekli: »Zato ker Hebrejke niso kakor Egipčanke, kajti one so krepke in rodijo prej ko babice pridejo k njim.«',
        20: 'Zato je Bog z babicama dobro postopal in ljudstvo se je pomnožilo in postalo zelo mogočno.',
        21: 'Pripetilo se je, ker sta se babici bali Boga, da jima je naredil hiši.',
        22: 'Faraon je vsemu svojemu ljudstvu zapovedal, rekoč: »Vsakega sina, ki je rojen, boste vrgli v reko, vsaka hči pa naj bo rešena živa.«',
    },
    2: {
        1: 'Odšel je mož iz Lévijeve hiše in za ženo vzel Lévijevo hčer.',
        2: 'Ženska je spočela in rodila sina in ko je videla, da je bil čeden otrok, ga je skrivala tri mesece.',
        3: 'Ko pa ga ni mogla več skrivati, je zanj vzela pletenico iz ločja, jo namazala z blatom in s smolo in vanjo položila otroka in to položila v rogoz poleg rečnega brega.',
        4: 'Njegova sestra pa je stala daleč stran, da izve kaj se bo z njim zgodilo.',
        5: 'In dol je prišla faraonova hči, da se pri reki umije, njene služabnice pa so hodile vzdolž rečnega brega in ko je med rogozom zagledala pletenico, je poslala svojo služabnico, da odide ponjo.',
        6: 'Ko jo je ta odprla, je zagledala otroka in glej, dojenček je jokal. Do njega je imela sočutje ter rekla: »To je eden izmed hebrejskih otrok.«',
        7: 'Potem je njegova sestra rekla faraonovi hčeri: »Ali naj grem in k tebi pokličem dojiljo izmed hebrejskih žensk, da bo lahko otroka dojila zate?«',
        8: 'Faraonova hči ji je rekla: »Pojdi.« Deklica je odšla in poklicala otrokovo mater.',
        9: 'Faraonova hči ji je rekla: »Odnesi tega otroka proč in ga dôji zame, jaz pa ti bom dajala tvoja plačila.« In ženska je vzela otroka ter ga dojila.',
        10: 'Otrok je zrastel in privedla ga je k faraonovi hčeri in ta je postal njen sin. Njegovo ime je imenovala Mojzes. Rekla je: »Ker sem ga potegnila iz vode.«',
        11: 'Pripetilo se je v tistih dneh, ko je Mojzes odrasel, da je odšel k svojim bratom, gledal na njihova bremena in oprezal za Egipčanom, ki je udarjal Hebrejca, enega izmed njegovih bratov.',
        12: 'Pogledal je to pot in tisto pot in ko je videl, da tam ni bilo nobenega človeka, je Egipčana usmrtil in ga skril v pesek.',
        13: 'Ko je drug dan odšel ven, glej, dva moža izmed Hebrejcev sta se skupaj prepirala in temu, ki je storil napačno, je rekel: »Čemu udarjaš svojega rojaka?«',
        14: 'Ta pa je rekel: »Kdo te je naredil princa in sodnika nad nama? Ali me nameravaš ubiti, kakor si ubil Egipčana?« Mojzes se je zbal ter rekel: »Ta stvar se je zagotovo izvedela.«',
        15: 'Torej, ko je faraon slišal to stvar, je iskal Mojzesa, da ga ubije. Mojzes pa je pobegnil izpred faraonovega obličja in prebival v midjánski deželi in se usedel poleg vodnjaka.',
        16: 'Torej duhovnik iz Midjána je imel sedem hčera in prišle so, zajele vodo in napolnile korita, da bi napojile trop svojega očeta.',
        17: 'Prišli pa so pastirji ter jih odgnali proč, toda Mojzes je vstal, jim pomagal in napojil njihov trop.',
        18: 'Ko so prišle k svojemu očetu Reguélu, je rekel: »Kako je to, da ste danes prišle tako zgodaj?«',
        19: 'Rekle so: »Egipčan nas je osvobodil iz roke pastirjev in nam prav tako zajel dovolj vode in napojil trop.«',
        20: 'Svojim hčeram je rekel: »In kje je? Zakaj je to, da ste človeka pustile? Pokličite ga, da bo lahko jedel kruh.«',
        21: 'Mojzes je bil zadovoljen, da prebiva s človekom in ta je Mojzesu dal svojo hčer Cipóro.',
        22: 'Rodila mu je sina in njegovo ime je imenoval Geršóm, kajti rekel je: »Tujec sem bil v tuji deželi.«',
        23: 'Pripetilo se je tekom časa, da je egiptovski kralj umrl, Izraelovi otroci pa so vzdihovali zaradi razloga suženjstva in vpili in njihovo vpitje je zaradi razloga suženjstva prišlo do Boga.',
        24: 'Bog je slišal njihovo stokanje in Bog se je spomnil svoje zaveze z Abrahamom, Izakom in Jakobom.',
        25: 'Bog je pogledal na Izraelove otroke in Bog je imel do njih spoštovanje.',
    },
    3: {
        1: 'Torej Mojzes je varoval trop svojega tasta Jitra, midjánskega duhovnika in vodil trop k zadnjemu delu puščave in prišel h gori Boga, k Horebu.',
        2: 'Gospodov angel se mu je prikazal v ognjenem plamenu iz srede grma in pogledal je in glej, grm je gorel z ognjem, pa grm ni bil použit.',
        3: 'Mojzes je rekel: »Sedaj se bom obrnil vstran in pogledal ta velik prizor, zakaj grm ne zgori.«',
        4: 'Ko je Gospod videl, da se je obrnil vstran, da bi videl, je Bog iz srede grma zaklical k njemu ter rekel: »Mojzes, Mojzes.« Ta je rekel: »Tukaj sem.«',
        5: 'Rekel je: »Ne približaj se, svoje čevlje sezuj s svojih stopal, kajti prostor, na katerem stojiš, je sveta zemlja.«',
        6: 'Poleg tega je rekel: »Jaz sem Bog tvojega očeta, Bog Abrahama, Bog Izaka in Bog Jakoba.« In Mojzes je skril svoj obraz, kajti bal se je, da bi pogledal na Boga.',
        7: 'Gospod je rekel: »Zagotovo sem videl stisko svojega ljudstva, ki je v Egiptu in slišal njihovo vpitje zaradi njihovih preddelavcev, kajti poznam njihove bridkosti',
        8: 'in prišel sem dol, da jih osvobodim iz roke Egipčanov in jih privedem iz te dežele gor v dobro in veliko deželo, deželo, kjer tečeta mleko in med, v deželo Kánaancev, Hetejcev, Amoréjcev, Perizéjcev, Hivéjcev in Jebusejcev.',
        9: 'Zdaj torej, glej, k meni je prišlo vpitje Izraelovih otrok in videl sem tudi zatiranje, s kakršnim so jih Egipčani zatirali.',
        10: 'Pridi torej zdaj in jaz te bom poslal k faraonu, da lahko privedeš moje ljudstvo, Izraelove otroke, iz Egipta.«',
        11: 'Mojzes pa je Bogu rekel: »Kdo sem jaz, da bi šel k faraonu in da bi lahko Izraelove otroke privedel iz Egipta?«',
        12: 'Rekel je: »Zagotovo bom s teboj in to ti bodi simbol, da sem te jaz poslal. Ko boš ljudstvo privedel iz Egipta, boste na tej gori služili Bogu.«',
        13: 'Mojzes je Bogu rekel: »Glej, ko pridem k Izraelovim otrokom in jim bom rekel: ›K vam me je poslal Bog vaših očetov,‹ pa mi bodo rekli: ›Kakšno je njegovo ime?‹ Kaj naj jim rečem?«',
        14: 'Bog je Mojzesu rekel: »JAZ SEM, KI SEM.« Rekel je: »Tako boš govoril Izraelovim otrokom: ›JAZ SEM me je poslal k vam.‹«',
        15: 'Bog je Mojzesu poleg tega povedal: »Tako boš rekel Izraelovim otrokom: ›K vam me je poslal Gospod, Bog vaših očetov, Bog Abrahama, Bog Izaka in Bog Jakoba. To je moje ime na veke in to je moj spomin vsem rodovom.‹',
        16: 'Pojdi in zberi skupaj vse Izraelove starešine ter jim reci: ›Prikazal se mi je Gospod, Bog vaših očetov, Bog Abrahama, Izaka in Jakoba, rekoč: ›Zagotovo sem vas obiskal in videl to, kar vam je storjeno v Egiptu.‹«',
        17: 'In rekel sem: »Jaz vas bom privedel gor iz egiptovske stiske v deželo Kánaancev, Hetejcev, Amoréjcev, Perizéjcev, Hivéjcev in Jebusejcev, v deželo, kjer tečeta mleko in med.',
        18: 'Prisluhnili bodo tvojemu glasu in ti boš prišel, ti in Izraelove starešine, k egiptovskemu kralju in mu boste rekli: › Gospod, Bog Hebrejcev, se je srečal z nami in sedaj nas pusti iti, rotimo te, tri dni potovanja v divjino, da bomo lahko žrtvovali Gospodu, našemu Bogu.‹',
        19: 'Prepričan pa sem, da vam egiptovski kralj ne bo pustil oditi, ne, niti z mogočno roko ne.',
        20: 'Svojo roko bom iztegnil in Egipt udaril z vsemi čudeži, ki jih bom storil v njihovi sredi in nató vas bo pustil oditi.',
        21: 'Temu ljudstvu bom dal naklonjenost v očeh Egipčanov in zgodilo se bo, ko greste, da ne boste odšli prazni,',
        22: 'temveč si bo vsaka ženska izposodila od sosede in od tiste, ki začasno biva v njeni hiši, dragocenosti iz srebra in dragocenosti iz zlata in oblačil, in vi jih boste nadeli na svoje sinove in na svoje hčere in boste oplenili Egipčane.«',
    },
    4: {
        1: 'Mojzes je odgovoril in rekel: »Toda, glej, ne bodo mi verjeli niti prisluhnili mojemu glasu, kajti rekli bodo: › Gospod se ti ni prikazal.‹«',
        2: 'Gospod mu je rekel: »Kaj je to v tvoji roki?« Rekel je: »Palica.«',
        3: 'Rekel je: »Vrzi jo na tla.« Vrgel jo je na tla in ta je postala kača in Mojzes je pobegnil pred njo.',
        4: 'Gospod je rekel Mojzesu: »Iztegni svojo roko in jo primi za rep.« Iztegnil je svojo roko in jo ujel in v njegovi roki je postala palica.',
        5: '»Da bodo oni lahko verjeli, da se ti je prikazal Gospod, Bog njihovih očetov, Bog Abrahama, Bog Izaka in Bog Jakoba.«',
        6: 'Gospod mu je nadalje rekel: »Sedaj daj svojo roko v svoje naročje.« Svojo roko je položil v svoje naročje, ko pa jo je izvlekel, glej, je bila njegova roka gobava kakor sneg.',
        7: 'Rekel je: »Svojo roko ponovno daj v svoje naročje.« In ponovno je svojo roko položil v svoje naročje in izvlekel jo je iz svojega naročja in glej, ponovno je bila spremenjena kakor drugo njegovo meso.',
        8: '»Zgodilo se bo, če ti ne bodo verjeli niti prisluhnili glasu prvega znamenja, da bodo verjeli glasu zadnjega znamenja.',
        9: 'Zgodilo se bo, če ne bodo verjeli tudi tema dvema znamenjema niti prisluhnili tvojemu glasu, da boš iz reke zajel vodo in jo izlil na suho zemljo in voda, ki jo zajameš iz reke, bo na suhih tleh postala kri.«',
        10: 'Mojzes je Gospodu rekel: »Oh moj Gospod, jaz nisem zgovoren, niti poprej niti odkar si spregovoril svojemu služabniku, temveč sem počasen za govorjenje in počasnega jezika.«',
        11: 'Gospod mu je rekel: »Kdo je naredil človekova usta? Ali kdo naredi nemega ali gluhega ali da vidi ali slepega? Ali ne jaz, Gospod?',
        12: 'Sedaj torej pojdi in jaz bom s tvojimi usti in te učil kaj boš govoril.«',
        13: 'Rekel je: »Oh moj Gospod, pošlji, prosim te, po roki tistega, ki ga ti hočeš poslati.«',
        14: 'Gospodova jeza je bila vžgana zoper Mojzesa in rekel je: » Mar ni Lévijevec Aron tvoj brat? Vem, da lahko dobro govori. In tudi, glej, prihaja, da te sreča in ko te zagleda, bo v svojem srcu vesel.',
        15: 'Ti mu boš govoril in v njegova usta polagal besede in jaz bom s tvojimi usti in z njegovimi usti in vaju učil, kaj bosta storila.',
        16: 'On bo tvoj govornik ljudstvu in on bo, celó on bo tebi namesto ust in ti boš njemu namesto Boga.',
        17: 'In v svojo roko boš vzel to palico, s katero boš delal znamenja.«',
        18: 'Mojzes je odšel, se vrnil k svojemu tastu Jitru in mu rekel: »Pusti me iti, prosim te in se vrniti k mojim bratom, ki so v Egiptu in videti ali so še živi.« Jitro je Mojzesu rekel: »Pojdi v miru.«',
        19: 'Gospod je v Midjánu rekel Mojzesu: »Pojdi, vrni se v Egipt, kajti vsi ljudje, ki so ti stregli po življenju, so mrtvi.«',
        20: 'Mojzes je vzel svojo ženo in svoja sinova in jih posadil na osla in se vrnil v egiptovsko deželo in Mojzes je v svojo roko vzel Božjo palico.',
        21: 'Gospod je rekel Mojzesu: »Ko greš, da se vrneš v Egipt, glej, da boš pred faraonom storil vse te čudeže, ki sem jih položil v tvojo roko, toda jaz bom zakrknil njegovo srce, da ljudstvu ne bo dovolil oditi.',
        22: 'Faraonu boš rekel: ›Tako govori Gospod, Izrael je moj sin, celo moj prvorojenec‹',
        23: 'in jaz ti pravim: ›dovoli mojemu sinu oditi, da mi bo lahko služil. Če pa mu boš odklonil oditi, glej, bom ubil tvojega sina, celó tvojega prvorojenca.‹«',
        24: 'Pripetilo se je po poti v gostišče, da ga je srečal Gospod in si prizadeval, da ga ubije.',
        25: 'Tedaj je Cipóra vzela oster kamen in odrezala prednjo kožico svojega sina in jo vrgla k njegovim stopalom ter rekla: »Zagotovo si mi krvav soprog.«',
        26: 'Tako ga je pustil oditi. Potem je rekla: »Krvav soprog si zaradi obreze.«',
        27: 'Gospod je rekel Aronu: »Pojdi v divjino, da srečaš Mojzesa.« Ta je odšel in ga srečal na gori Boga ter ga poljubil.',
        28: 'Mojzes je povedal Aronu vse besede Gospoda, ki ga je poslal in vsa znamenja, ki mu jih je zapovedal.',
        29: 'Mojzes in Aron sta odšla ter zbrala skupaj vse starešine Izraelovih otrok',
        30: 'in Aron je govoril vse besede, ki jih je Gospod govoril Mojzesu in v očeh ljudstva storil znamenja.',
        31: 'Ljudje so verovali in ko so slišali, da je Gospod obiskal Izraelove otroke in da je pogledal na njihovo stisko, potem so sklonili svoje glave in oboževali.',
    },
    5: {
        1: 'Potem sta Mojzes in Aron vstopila in faraonu rekla: »Tako govori Gospod, Izraelov Bog: ›Pusti moje ljudstvo oditi, da bodo v divjini lahko imeli praznovanje meni.‹«',
        2: 'Faraon je rekel: »Kdo je Gospod, da bi ubogal njegov glas, da bi pustil Izraela oditi? Ne poznam Gospoda niti Izraelu ne bom pustil oditi.«',
        3: 'Rekel je: »Bog Hebrejcev se je srečal z nami. Pusti nas oditi, prosimo te, tri dni potovanja v puščavo in žrtvujemo Gospodu, našemu Bogu, da on ne pade na nas s kužno boleznijo ali z mečem.«',
        4: 'Egiptovski kralj pa jima je rekel: »Zakaj vidva, Mojzes in Aron, pustita ljudstvo od njihovih del? Odidita k svojim bremenom.«',
        5: '§ Faraon je rekel: »Glejta, ljudstva dežele je torej mnogo, vidva pa jim delata počitek pred njihovimi bremeni.«',
        6: 'Faraon je istega dne zapovedal preddelavcem ljudstva in njihovim nadzornikom, rekoč:',
        7: '»Ljudstvu ne boste več dajali slame, da delajo opeko, kakor poprej. Naj gredo in sami nabirajo slamo.',
        8: 'Število opek, ki so jih naredili poprej, boste položili nanje. Ne boste zmanjšali od tega dolga, kajti brezdelni so, zato vpijejo, rekoč: ›Pojdimo in žrtvujmo našemu Bogu.‹',
        9: 'Več dela naj bo položenega na ljudi, da se bodo lahko trudili s tem in naj se ne ozirajo na prazne besede.«',
        10: 'Preddelavci ljudstva so odšli ven in njihovi nadzorniki in ljudstvu spregovorili, rekoč: »Tako govori faraon: ›Ne bom vam dajal slame.',
        11: 'Pojdite, dobite slamo kjer jo lahko najdete, vendar dolg vašega dela ne bo zmanjšan.‹«',
        12: '§ Tako je bilo ljudstvo razkropljeno naokoli po vsej egiptovski deželi, da zbira strnišče namesto slame.',
        13: 'Preddelavci so jih priganjali, rekoč: »Izpolnjujte svoja dela, svoje dnevne naloge, kakor ko je bila slama.«',
        14: 'Nadzorniki Izraelovih otrok, ki so jih faraonovi preddelavci postavili nadnje, so bili pretepeni in zahtevali: »Zakaj niste izpolnili svoje naloge v izdelavi opek, tako včeraj in danes, kakor poprej?«',
        15: 'Potem so nadzorniki Izraelovih otrok prišli in vpili k faraonu, rekoč: »Zakaj tako postopaš s svojimi služabniki?',
        16: 'Nobena slama ni dana tvojim služabnikom, oni pa nam pravijo: ›Delajte opeko.‹ Glej, tvoji služabniki so pretepeni, toda krivda je na tvojem lastnem ljudstvu.«',
        17: 'Toda rekel jim je: »Vi ste brezdelni, vi ste brezdelni, zato pravite: ›Pojdimo in naredimo žrtvovanje Gospodu.‹',
        18: 'Pojdite torej sedaj in delajte, kajti slama vam ne bo dana, vendar boste izročili število opek.«',
        19: 'Nadzorniki Izraelovih otrok so videli, da so bili v zlem primeru, potem ko je bilo rečeno: »Ne boste zmanjšali dolga od opek svoje dnevne naloge.«',
        20: 'Srečali so Mojzesa in Arona, ki sta stala na poti, ko so prišli od faraona',
        21: 'in jima rekli: » Gospod naj pogleda na vaju in sodi, ker sta storila našemu okusu, da je preziran v faraonovih očeh in v očeh njegovih služabnikov, da položi meč v njihovo roko, da nas ubijejo.«',
        22: 'Mojzes se je vrnil h Gospodu ter rekel: »Gospod, zakaj si tako zlo ravnal s tem ljudstvom? Zakaj je to, da si me poslal?',
        23: 'Kajti odkar sem prišel k faraonu, da govorim v tvojem imenu, je temu ljudstvu storil zlo niti sploh nisi osvobodil svojega ljudstva.«',
    },
    6: {
        1: 'Potem je Gospod rekel Mojzesu: »Sedaj boš videl kaj bom storil faraonu, kajti z močno roko jih bo pustil oditi in z močno roko jih bo pognal iz svoje dežele.«',
        2: 'Bog je Mojzesu spregovoril in mu rekel: »Jaz sem Gospod.',
        3: 'Prikazal sem se Abrahamu, Izaku in Jakobu po imenu Bog Vsemogočni, toda po svojem imenu, Jahve, jim nisem bil znan.',
        4: 'Z njimi sem utrdil tudi svojo zavezo, da jim dam kánaansko deželo, deželo njihovega popotovanja, v kateri so bili tujci.',
        5: 'In tudi sam sem slišal stokanje Izraelovih otrok, ki jih Egipčani držijo v suženjstvu, in spomnil sem se svoje zaveze.',
        6: 'Zatorej reci Izraelovim otrokom: ›Jaz sem Gospod in jaz vas bom izpeljal izpod bremen Egipčanov in jaz vas bom odstranil iz njihovega suženjstva in jaz vas bom odkupil z iztegnjenim laktom in z velikimi sodbami.',
        7: 'Jaz vas bom vzel k sebi za ljudstvo in jaz vam bom Bog in vi boste vedeli, da jaz sem Gospod, vaš Bog, ki vas osvobaja izpod bremen Egipčanov.',
        8: 'Jaz vas bom privedel v deželo, v zvezi s katero sem prisegel, da jo dam Abrahamu, Izaku in Jakobu, in dal vam jo bom za dediščino. Jaz sem Gospod.‹«',
        9: 'Mojzes je tako govoril Izraelovim otrokom. Toda Mojzesu niso prisluhnili zaradi tesnobe duha in zaradi krutega suženjstva.',
        10: 'Gospod je spregovoril Mojzesu, rekoč:',
        11: '»Vstopi in govori faraonu, egiptovskemu kralju, da naj pusti Izraelove otroke oditi iz njegove dežele.«',
        12: 'Mojzes je govoril pred Gospodom, rekoč: »Glej, Izraelovi otroci mi niso prisluhnili. Kako bo potem faraon slišal mene, ki sem neobrezanih ustnic?«',
        13: '§ Gospod je govoril Mojzesu in Aronu ter jima naložil skrb za Izraelove otroke in faraona, egiptovskega kralja, da Izraelove otroke privedeta iz egiptovske dežele.',
        14: 'To so poglavarji hiš svojih očetov. Sinovi Rubena, Izraelovega prvorojenca: Henoh in Palú, Hecrón in Karmí; to so bile Rubenove družine.',
        15: 'Simeonovi sinovi: Jemuél, Jamín, Ohad, Jahín, Cohar in Šaúl, sin kánaanske ženske. To so Simeonove družine.',
        16: 'To so imena Lévijevih sinov glede na njihove rodove: Geršón, Kehát in Merarí. Let Lévijevega življenja je bilo sto sedemintrideset let.',
        17: 'Geršónova sinova: Libni in Šimí, glede na njuni družini.',
        18: 'Kehátovi sinovi: Amrám, Jichár, Hebrón in Uziél. Let Kehátovega življenja je bilo sto triintrideset let.',
        19: 'Meraríjeva sinova: Mahlí in Muší. To so družine Lévijevcev glede na svoje rodove.',
        20: 'Amrám si je za ženo vzel Johébedo, sestro svojega očeta. Rodila mu je Arona in Mojzesa. Let Amrámovega življenja je bilo sto sedemintrideset let.',
        21: 'Jichárjevi sinovi: Korah, Nefeg in Zihrí.',
        22: 'Uziélovi sinovi: Mišaél, Elicafán in Sitrí.',
        23: 'Aron si je vzel za ženo Elišébo, Aminadábovo hčer, Nahšónovo sestro. Rodila mu je Nadába in Abihúja, Eleazarja in Itamárja.',
        24: 'Korahovi sinovi: Asír, Elkaná in Abiasáf. To so družine Korahovcev.',
        25: 'Aronov sin Eleazar si je za ženo vzel eno izmed Putiélovih hčera. Rodila mu je Pinhása. To so poglavarji očetov Lévijevcev glede na njihove družine.',
        26: 'To sta tista Mojzes in Aron, ki jima je Gospod rekel: »Izpeljita Izraelove otroke iz egiptovske dežele glede na njihove vojske.«',
        27: 'To sta tista, ki sta govorila egiptovskemu kralju faraonu, da izpeljeta Izraelove otroke iz Egipta. To sta tista Mojzes in Aron.',
        28: 'In pripetilo se je na dan, ko je Gospod spregovoril Mojzesu v egiptovski deželi,',
        29: 'da je Gospod spregovoril Mojzesu, rekoč: »Jaz sem Gospod. Govori faraonu, egiptovskemu kralju vse, kar ti povem.«',
        30: 'Mojzes je rekel pred Gospodom: »Glej, jaz sem neobrezanih ustnic in kako mi bo faraon prisluhnil?«',
    },
    7: {
        1: 'Gospod je rekel Mojzesu: »Poglej, naredil sem te faraonu za boga. Tvoj brat Aron pa bo tvoj prerok.',
        2: 'Govoril boš vse, kar ti ukažem. Tvoj brat Aron pa bo govoril faraonu, da Izraelove otroke pošlje iz svoje dežele.',
        3: 'Zakrknil bom faraonovo srce in pomnožil svoja znamenja in svoje čudeže v egiptovski deželi.',
        4: 'Toda faraon vama ne bo prisluhnil, da bom svojo roko lahko položil nad Egipt in izpeljal svoje vojske in svoje ljudstvo, Izraelove otroke, z velikimi sodbami, iz egiptovske dežele.',
        5: 'In Egipčani bodo spoznali, da jaz sem Gospod, ko iztegnem svojo roko nad Egipt in Izraelove otroke izpeljem izmed njih.«',
        6: 'Mojzes in Aron sta storila; kakor jima je Gospod zapovedal, tako sta storila.',
        7: 'Mojzes je bil star osemdeset let, Aron pa triinosemdeset let, ko sta govorila faraonu.',
        8: 'Gospod je spregovoril Mojzesu in Aronu, rekoč:',
        9: '»Ko vama bo faraon rekel, rekoč: ›Pokažita mi čudež za vas,‹ potem boš rekel Aronu: ›Vzemi svojo palico in jo vrzi pred faraona‹ in le-ta bo postala kača.«',
        10: 'Mojzes in Aron sta odšla k faraonu in storila, kakor jima je Gospod zapovedal. Aron je svojo palico vrgel pred faraona in pred njegove služabnike in postala je kača.',
        11: 'Potem je tudi faraon poklical modre može in čarodeje. Torej egiptovski čarovniki, tudi oni so na podoben način storili s svojimi izrekanji urokov.',
        12: 'Kajti vsak je vrgel svojo palico in postale so kače, toda Aronova palica je požrla njihove palice.',
        13: '§ In zakrknil je faraonovo srce, da jim ni prisluhnil, kakor je rekel Gospod.',
        14: 'Gospod je rekel Mojzesu: »Faraonovo srce je zakrknjeno, odklanja pustiti ljudstvo, da odide.',
        15: 'Zjutraj pojdi k faraonu. Glej, on gre ven k vodi in [ko] pride, boš stal nasproti pri rečnem bregu in palico, ki je bila spremenjena v kačo, boš vzel v svojo roko.',
        16: 'Rekel mu boš: › Gospod, Bog Hebrejcev, me je poslal k tebi, rekoč: ›Odpusti moje ljudstvo, da mi bodo lahko služili v divjini‹ in glej, doslej nisi hotel poslušati.‹',
        17: 'Tako govori Gospod: ›V tem boš vedel, da sem jaz Gospod. Glej, s palico, ki je v moji roki, bom udaril na vode, ki so v reki in spremenjene bodo v kri.',
        18: 'Ribe, ki so v reki, bodo poginile in reka bo zaudarjala in Egipčanom se bo gnusilo piti vodo iz reke.‹«',
        19: 'Gospod je spregovoril Mojzesu: »Reci Aronu: ›Vzemi svojo palico in iztegni svojo roko nad egiptovske vode, nad njihove vodotoke, nad njihove reke, nad njihove ribnike in nad vse njihove vodne tolmune, da bodo lahko postali kri in da bo lahko kri po vsej egiptovski deželi, tako v posodah iz lesa, kakor v posodah iz kamna.‹«',
        20: 'Mojzes in Aron sta storila tako kakor je Gospod zapovedal in ta je dvignil palico in udaril vode, ki so bile v reki, pred faraonovim pogledom in pogledom njegovih služabnikov, in vse vode, ki so bile v reki, so bile spremenjene v kri.',
        21: 'Ribe, ki so bile v reki, so poginile in reka je smrdela in Egipčani niso mogli piti vode iz reke in kri je bila po vsej egiptovski deželi.',
        22: 'Egiptovski čarovniki so tako storili s svojimi izrekanji urokov in faraonovo srce je bilo zakrknjeno niti jima ni prisluhnil, kakor je rekel Gospod.',
        23: 'Faraon se je obrnil in odšel v svojo hišo niti tudi ni k temu usmeril svojega srca.',
        24: 'Vsi Egipčani so okoli reke kopáli za vodo, da [bi] pili, kajti vode iz reke niso mogli piti.',
        25: 'Dopolnjenih je bilo sedem dni, potem ko je Gospod udaril reko.',
    },
    8: {
        1: 'Gospod je spregovoril Mojzesu: »Pojdi k faraonu in mu reci: ›Tako govori Gospod: ›Odpusti moje ljudstvo, da mi bodo lahko služili.‹‹',
        2: 'Če pa odkloniš, da jih odpustiš, glej, bom vse tvoje meje udaril z žabami.',
        3: 'Reke bodo rodile žab v obilju, ki bodo šle gor in prišle v tvojo hišo, v tvojo spalnico, na tvojo posteljo, v hiše tvojih služabnikov, na tvoje ljudstvo, v tvoje peči in v tvoje nečke.',
        4: 'Žabe bodo prišle tako nate, kakor na tvoje ljudstvo in na vse tvoje služabnike.«',
        5: 'Gospod je spregovoril Mojzesu: »Reci Aronu: ›Iztegni svojo roko s svojo palico nad vodotoke, nad reke in nad ribnike ter povzroči žabam, da pridejo nad egiptovsko deželo.‹«',
        6: 'Aron je iztegnil svojo roko nad egiptovske vode in žabe so prišle gor ter pokrile egiptovsko deželo.',
        7: 'Čarovniki so tako storili s svojimi izrekanji urokov in nad egiptovsko deželo privedli žabe.',
        8: 'Potem je faraon dal poklicati Mojzesa in Arona ter rekel: »Rotita Gospoda, da lahko odstrani žabe od mene in od mojega ljudstva; jaz pa bom pustil ljudstvu oditi, da bodo lahko žrtvovali Gospodu.«',
        9: 'Mojzes je rekel faraonu: »Slava nad menoj. Kdaj naj rotim zate in za tvoje služabnike in za tvoje ljudstvo, da uniči žabe pred teboj in tvojimi hišami, da bodo lahko preostale samo v reki?«',
        10: 'Rekel je: »Jutri.« Rekel je: » To bodi glede na tvojo besedo, da lahko spoznaš, da ni nikogar podobnega Gospodu, našemu Bogu.',
        11: 'Žabe bodo odšle od tebe in od tvojih hiš in od tvojih služabnikov in od tvojega ljudstva. Preostale bodo samo še v reki.«',
        12: 'Mojzes in Aron sta odšla izpred faraona. Mojzes je klical h Gospodu zaradi žab, ki jih je privedel zoper faraona.',
        13: 'Gospod je storil glede na Mojzesovo besedo in žabe so poginile po hišah, po vaseh in po poljih.',
        14: 'Zbrali so jih skupaj na kupe in dežela se je usmradila.',
        15: 'Toda ko je faraon videl, da je bil predah, je zakrknil svoje srce in jima ni prisluhnil, kakor je rekel Gospod.',
        16: '§ Gospod je rekel Mojzesu: »Reci Aronu: ›Iztegni svojo palico in udari prah dežele, da [iz] tega lahko nastanejo uši po vsej egiptovski deželi.‹«',
        17: '§ Storila sta tako, kajti Aron je iztegnil svojo roko s svojo palico in udaril prah dežele in [iz] tega so nastale uši na človeku in na živali. [Iz] vsega prahu dežele so nastale uši po vsej egiptovski deželi.',
        18: '§ Čarovniki so tako storili s svojimi izrekanji urokov, da odstranijo uši, toda niso mogli, tako so bile uši na človeku in na živali.',
        19: 'Potem so čarovniki rekli faraonu: »To je Božji prst.« Faraonovo srce pa je bilo zakrknjeno in jim ni prisluhnil, kakor je rekel Gospod.',
        20: 'Gospod je rekel Mojzesu: »Vstani zgodaj zjutraj in stopi pred faraona. Glej, ta prihaja k vodi in mu reci: ›Tako govori Gospod: ›Pusti moje ljudstvo oditi, da mi bodo lahko služili.',
        21: 'Ali pa, če ne boš hotel pustiti mojemu ljudstvu oditi, glej, bom poslal roje muh nate, na tvoje služabnike, na tvoje ljudstvo in v tvoje hiše. Hiše Egipčanov bodo polne rojev muh in tudi zemlja, na kateri so.',
        22: 'Na ta dan bom oddvojil gošensko deželo, v kateri prebiva moje ljudstvo, da tam ne bo rojev muh; z namenom, da lahko spoznaš, da sem jaz Gospod v sredi zemlje.',
        23: 'Jaz bom položil ločnico med svojim ljudstvom in tvojim ljudstvom. Jutri bo to znamenje.‹«',
        24: '§ In Gospod je storil tako. Prišel je nadležen roj muh v faraonovo hišo, v hiše njegovih služabnikov in v vso egiptovsko deželo. Dežela je bila okužena zaradi roja muh.',
        25: 'Faraon je dal poklicati Mojzesa in Arona ter rekel: »Pojdite, žrtvujte vašemu Bogu v deželi.«',
        26: 'Mojzes pa je rekel: »Ni primerno tako storiti, kajti ogabnost Egipčanom bomo žrtvovali Gospodu, našemu Bogu. Glej, pred njihovimi očmi bomo žrtvovali gnusobo Egipčanov in mar nas ne bodo kamnali?',
        27: 'Šli bomo tri dni potovanja v divjino in žrtvovali Gospodu, našemu Bogu, kakor nam bo zapovedal.«',
        28: 'Faraon pa je rekel: »Pustil vam bom oditi, da boste lahko žrtvovali Gospodu, svojemu Bogu, v divjini; samo ne boste odšli zelo daleč proč. Rotite zame.«',
        29: 'Mojzes je rekel: »Glej, ven grem od tebe in rotil bom Gospoda, da roji muh lahko jutri odidejo od faraona, od njegovih služabnikov in od njegovega ljudstva, toda faraon naj ne postopa več varljivo z nedovoljevanjem ljudstvu, da gre žrtvovat Gospodu.«',
        30: 'Mojzes je odšel izpred faraona in rotil Gospoda.',
        31: 'Gospod je storil glede na Mojzesovo besedo in roje muh odstranil od faraona, od njegovih služabnikov in od njegovega ljudstva. Niti ena ni preostala.',
        32: 'Faraon pa je tudi tokrat zakrknil svoje srce niti ni hotel odpustiti ljudstva.',
    },
    9: {
        1: 'Potem je Gospod rekel Mojzesu: »Pojdi noter k faraonu in mu povej: ›Tako govori Gospod, Bog Hebrejcev: ›Pusti moje ljudstvo oditi, da mi bodo lahko služili.‹',
        2: 'Kajti, če odkloniš, da bi jih pustil oditi in jih hočeš trdno držati,',
        3: 'glej, Gospodova roka je na tvoji živini, ki je na polju, na konjih, na oslih, na kamelah, na volih in na ovcah. Tam bo zelo nadležna živinska kuga.',
        4: 'Gospod bo oddvojil med izraelsko živino in egiptovsko živino in nič ne bo poginilo, od vsega, kar je [last] Izraelovih otrok.‹«',
        5: 'Gospod je določil čas, rekoč: »Jutri bo Gospod to stvar storil v deželi.«',
        6: 'Gospod je naslednji dan storil to stvar in vsa egiptovska živina je poginila, toda izmed živine Izraelovih otrok ni poginila niti ena.',
        7: 'Faraon je poslal in glej, niti ena izmed izraelske živine ni poginila. Faraonovo srce pa je bilo zakrknjeno in ljudstvu ni pustil oditi.',
        8: 'Gospod je rekel Mojzesu in Aronu: »K sebi vzemita prgišča pepela iz talilne peči in naj ga Mojzes potrese proti nebu pred faraonovimi očmi.',
        9: 'Ta bo postal droben prah po vsej egiptovski deželi in tvori bodo izbruhnili z mehurji na ljudeh in na živali po vsej egiptovski deželi.«',
        10: 'Vzela sta pepel iz talilne peči in stala pred faraonom. Mojzes ga je potresel proti nebu in ta je postal tvor, ki je izbruhnil z mehurji na ljudeh in na živali.',
        11: 'Čarovniki pa zaradi tvorov niso mogli stati pred Mojzesom, kajti tvor je bil na čarovnikih in na vseh Egipčanih.',
        12: 'Gospod pa je zakrknil faraonovo srce in ta jima ni prisluhnil, kakor je Gospod govoril Mojzesu.',
        13: 'Gospod je rekel Mojzesu: »Vstani zgodaj zjutraj in stopi pred faraona ter mu reci: ›Tako govori Gospod, Bog Hebrejcev: ›Pusti moje ljudstvo oditi, da mi bodo lahko služili.‹',
        14: 'Kajti tokrat bom vse svoje nadloge poslal na tvoje srce in na tvoje služabnike in na tvoje ljudstvo, da boš lahko vedel, da na vsej zemlji ni nikogar podobnega meni.',
        15: 'Kajti sedaj bom iztegnil svojo roko, da lahko udarim tebe in tvoje ljudstvo s kužno boleznijo, ti pa boš iztrebljen z zemlje.',
        16: 'Zagotovo sem te dvignil zaradi tega razloga, da pokažem na tebi svojo moč, in da bo moje ime lahko razglašeno po vsej zemlji.',
        17: 'Doklej se povišuješ zoper moje ljudstvo, da jim nočeš pustiti oditi?',
        18: 'Glej, jutri ob tem času bom povzročil, da bo deževala zelo boleča toča, kakršne ni bilo v Egiptu od njegovega nastanka celo do sedaj.',
        19: 'Pošlji torej sedaj in zberi svojo živino in vse, kar imaš na polju, kajti na vsakega človeka in žival, ki bo najdena na polju in ne bo privedena domov, bo nanje priletela toča in bodo umrli.‹«',
        20: 'Kdor se je med faraonovimi služabniki bal Gospodove besede, je svoje služabnike in svojo živino primoral, da so pobegnili v hiše,',
        21: 'kdor pa se ni oziral na Gospodovo besedo, je svoje služabnike in svojo živino pustil na polju.',
        22: 'Gospod je rekel Mojzesu: »Iztegni svojo roko proti nebu, da bo lahko toča po vsej egiptovski deželi, na ljudeh, na živali in na vsakem poljskem zelišču po vsej egiptovski deželi.«',
        23: 'Mojzes je svojo palico iztegnil proti nebu in Gospod je poslal grmenje in točo in spotoma je ogenj padal na zemljo; Gospod je deževal točo na egiptovsko deželo.',
        24: 'Tako je bila tam toča in ogenj, pomešan s točo, zelo boleč, takšen kot ni bilo nobenega podobnega temu po vsej egiptovski deželi, odkar je postala narod.',
        25: 'Toča je udarila povsod, po vsej egiptovski deželi vse, kar je bilo na polju, tako človeka kakor žival. Toča je udarila vsako zel na polju in zlomila vsako drevo na polju.',
        26: 'Samo v gošenski deželi, kjer so bili Izraelovi otroci, tam ni bilo toče.',
        27: 'Faraon je poslal in dal poklicati Mojzesa in Arona ter jima rekel: »Tokrat sem grešil. Gospod je pravičen, jaz in moje ljudstvo pa smo zlobni.',
        28: 'Rotita Gospoda (kajti dovolj je), da ne bo več mogočnih grmenj in toče, in jaz vam bom pustil oditi in ne boste več ostali.«',
        29: 'Mojzes mu je rekel: »Takoj, ko odidem iz mesta, bom razširil svoje roke h Gospodu in grmenje bo prenehalo niti nič več ne bo toče, da lahko spoznaš, da je zemlja Gospodova.',
        30: 'Toda kar se tiče tebe in tvojih služabnikov vem, da se še ne boste bali Gospoda Boga.«',
        31: 'Udarjena sta bila lan in ječmen, kajti ječmen je bil v klasu, lan pa je bil [v] cvetu.',
        32: 'Toda pšenica in pira nista bili udarjeni, kajti nista bili zreli.',
        33: 'Mojzes je odšel iz mesta od faraona in svoje roke razširil h Gospodu. Grmenja in toča sta prenehali in dež se ni izlival na zemljo.',
        34: 'Ko pa je faraon videl, da so dež, toča in grmenja prenehali, je še bolj grešil in zakrknil svoje srce, on in njegovi služabniki.',
        35: 'Faraonovo srce je bilo zakrknjeno niti ni hotel pustiti Izraelovih otrok oditi, kakor je Gospod govoril po Mojzesu.',
    },
    10: {
        1: 'Gospod je rekel Mojzesu: »Pojdi noter k faraonu, kajti zakrknil sem njegovo srce in srce njegovih služabnikov, da lahko ta svoja znamenja pokažem pred njim,',
        2: 'in da ti lahko poveš v ušesa svojih sinov in sinov svojih sinov, kakšne stvari sem storil v Egiptu in moja znamenja, ki sem jih storil med njimi, da boste lahko spoznali, kako [to], da sem jaz Gospod.«',
        3: 'Mojzes in Aron sta vstopila k faraonu ter mu rekla: »Tako govori Gospod, Bog Hebrejcev: ›Doklej boš odklanjal, da se ponižaš pred menoj? Pusti moje ljudstvo oditi, da mi bodo lahko služili.',
        4: 'Ali pa, če odkloniš, da pustiš moje ljudstvo oditi, glej, bom jutri v tvojo pokrajino privedel leteče kobilice.',
        5: 'Pokrile bodo obličje zemlje, da nekdo ne bo mogel videti zemlje. Pojedle bodo preostanek tega, kar je ušlo, kar vam ostaja od toče in pojedle bodo vsako drevo, ki vam raste zunaj polja.',
        6: 'Napolnile bodo tvoje hiše in hiše vseh tvojih služabnikov in hiše vseh Egipčanov, kar niti tvoji očetje niti očetje tvojih očetov niso videli od dneva, ko so bili na zemlji, do današnjega dne.‹« In obrnil se je ter odšel ven od faraona.',
        7: 'Faraonovi služabniki so mu rekli: »Doklej nam bo ta človek zanka? Pusti ljudi oditi, da bodo lahko služili Gospodu, svojemu Bogu. Mar še ne veš, da je Egipt uničen?«',
        8: 'Mojzes in Aron sta bila ponovno privedena k faraonu. Rekel jima je: »Pojdite, služite Gospodu, svojemu Bogu, toda kdo so tisti, ki bodo šli?«',
        9: 'Mojzes je rekel: »Šli bomo s svojimi mladimi in s svojimi starimi, s svojimi sinovi in s svojimi hčerami in s svojimi tropi in s svojimi čredami bomo šli, kajti imeti moramo praznik Gospodu.«',
        10: 'Rekel jima je: »Naj bo Gospod tako z vami, kakor bom jaz pustil oditi vam in vašim malčkom. Glejta na to, kajti zlo je pred vami.',
        11: 'Ne tako. Pojdite sedaj vi, ki ste možje in služite Gospodu, kajti to ste si želeli.« In izgnana sta bila izpred faraonove prisotnosti.',
        12: 'Gospod je rekel Mojzesu: »Iztegni svojo roko nad egiptovsko deželo zaradi letečih kobilic, da bodo lahko prišle nad egiptovsko deželo in pojedle vsako zemeljsko zelišče, celó vse, kar je pustila toča.«',
        13: 'Mojzes je iztegnil svojo palico nad egiptovsko deželo in Gospod je ves ta dan prinašal vzhodnik nad deželo in vso to noč, in ko je bilo jutro, je vzhodnik prinesel leteče kobilice.',
        14: 'Leteče kobilice so se dvignile nad vso egiptovsko deželo in počivale po vseh egiptovskih pokrajinah. Bile so zelo nadležne. Pred njimi ni bilo takšnih letečih kobilic kakor te niti takšnih ne bo za njimi.',
        15: 'Kajti pokrile so obličje celotne zemlje, tako da je bila dežela temna. Pojedle so vsa zelišča dežele in vse sadje dreves, ki jih je pustila toča. Niti ena zelena stvar ni preostala na drevesih ali na poljskih zeliščih po vsej egiptovski deželi.',
        16: 'Potem je faraon v naglici dal poklicati Mojzesa in Arona ter rekel: »Grešil sem zoper Gospoda, svojega Boga in zoper vaju.',
        17: 'Zdaj torej oprostita, prosim vaju, moj greh, samo še tokrat in rotita Gospoda, svojega Boga, da mi lahko odvzame samo to smrt.«',
        18: 'In odšel je ven od faraona in rotil Gospoda.',
        19: '§ Gospod je [veter] obrnil [v] mogočen močan zahodnik, ki je odnesel leteče kobilice in jih vrgel v Rdeče morje. Tam ni ostala niti ena leteča kobilica po vseh egiptovskih pokrajinah.',
        20: 'Toda Gospod je zakrknil faraonovo srce, tako da ta ni hotel pustiti Izraelovih otrok oditi.',
        21: 'Gospod je rekel Mojzesu: »Iztegni svojo roko proti nebu, da bo lahko tam tema nad egiptovsko deželo, celó tema, ki se jo bo lahko čutilo.«',
        22: 'Mojzes je iztegnil svojo roko proti nebu in tri dni je bila gosta tema po vsej egiptovski deželi.',
        23: 'Drug drugega niso videli niti tri dni ni nihče vstal iz svojega kraja, toda vsi Izraelovi otroci so imeli v svojih prebivališčih svetlobo.',
        24: 'Faraon je klical k Mojzesu ter rekel: »Pojdite, služite Gospodu. Samo vaši tropi in vaše črede naj ostanejo; naj gredo z vami tudi vaši malčki.«',
        25: 'Mojzes je rekel: »Moraš nam dati tudi klavne daritve in žgalne daritve, da bomo lahko darovali Gospodu, svojemu Bogu.',
        26: 'Tudi naša živina bo šla z nami. Niti kopito ne bo ostalo zadaj, kajti od nje moramo vzeti, da služimo Gospodu, svojemu Bogu in ne vemo s čim moramo služiti Gospodu, dokler ne pridemo tja.«',
        27: 'Toda Gospod je zakrknil faraonovo srce in ta jim ni hotel pustiti oditi.',
        28: 'Faraon mu je rekel: »Spravi se od mene, pazi se, da ne vidiš več mojega obraza, kajti na ta dan, [ko] zagledaš moj obraz, boš umrl.«',
        29: 'Mojzes je rekel: »Dobro si govoril, tvojega obraza ne bom več ponovno videl.«',
    },
    11: {
        1: 'Gospod je rekel Mojzesu: »Še eno nadlogo več bom privedel nad faraona in nad Egipt, potem vam bo pustil oditi. Ko vam bo pustil oditi, vas bo zagotovo vse skupaj sunil od tod.',
        2: 'Govori torej v ušesa ljudstvu in naj si vsak mož izposodi od svojega soseda in vsaka ženska od svoje sosede dragocenosti iz srebra in dragocenosti iz zlata.«',
        3: 'Gospod je dal ljudstvu naklonjenost v očeh Egipčanov. Poleg tega je bil človek Mojzes zelo velik v egiptovski deželi, v očeh faraonovih služabnikov in v očeh ljudstva.',
        4: 'Mojzes je rekel: »Tako govori Gospod: ›Okoli polnoči bom odšel ven, v sredo Egipta.',
        5: 'Vsi prvorojenci v egiptovski deželi bodo umrli, od faraonovega prvorojenca, ki sedi na njegovem prestolu, celo do prvorojenca dekle, ki je za mlinom in vse prvorojeno od živali.',
        6: 'Veliko vpitje bo po vsej egiptovski deželi, kot takšnega tam ni bilo niti ne bo več podobnega temu.',
        7: 'Toda zoper kateregakoli izmed Izraelovih otrok niti pes ne bo premaknil svojega jezika, zoper človeka ali žival, da boste lahko vedeli, kako Gospod postavlja razliko med Egipčani in Izraelom.‹',
        8: 'Vsi ti tvoji služabniki bodo prišli dol k meni in se mi priklonili, rekoč: ›Pojdi ven ti in vse ljudstvo, ki ti sledi.‹ In potem bom šel ven.« In od faraona je odšel v veliki jezi.',
        9: 'Gospod je rekel Mojzesu: »Faraon vama ne bo prisluhnil, da bodo moji čudeži lahko pomnoženi v egiptovski deželi.«',
        10: 'Mojzes in Aron sta vse te čudeže storila pred faraonom, Gospod pa je zakrknil faraonovo srce, tako da ta ne bi pustil Izraelovih otrok oditi ven iz svoje dežele.',
    },
    12: {
        1: 'Gospod je spregovoril Mojzesu in Aronu v egiptovski deželi, rekoč:',
        2: '»Ta mesec vam bo začetek mesecev. Ta vam bo prvi mesec v letu.',
        3: 'Govorita vsej Izraelovi skupnosti, rekoč: ›V desetem dnevu tega meseca si bo vsakdo vzel jagnje, glede na hišo svojih očetov, jagnje za hišo‹',
        4: 'in če bo družina premajhna za jagnje, naj ga on in njegov sosed, poleg njegove hiše, vzameta glede na število duš. Vsak človek bo glede na svoje prehranjevanje preštet na jagnje.',
        5: 'Vaše jagnje bo brez pomanjkljivosti, samec prvega leta. Vzeli ga boste izmed ovc ali izmed koz.',
        6: 'Varovali ga boste do štirinajstega dne istega meseca in celoten zbor Izraelove skupnosti ga bo zvečer zaklal.',
        7: 'Vzeli bodo od krvi in le-to potegnili s črto na dva podboja in na naddurje hiš, v katerih ga bodo jedli.',
        8: 'In v tej noči bodo jedli meso, pečeno na ognju in nekvašen kruh, in z grenkimi zelišči ga bodo jedli.',
        9: 'Ne jejte od njega surovega niti vsega skuhanega z vodo, temveč pečenega na ognju. Njegovo glavo z njegovimi nogami in z njegovo drobovino.',
        10: 'In ničesar od njega ne boste pustili do jutra. To, kar od njega ostane do jutra, boste sežgali z ognjem.',
        11: 'Tako ga boste jedli: z vašimi ledji opasanimi, vašimi čevlji na vaših stopalih in vašo palico v vaši roki. Jedli ga boste v naglici. To je Gospodova pasha.',
        12: 'Kajti to noč pojdem skozi egiptovsko deželo in udaril bom vse prvorojeno v egiptovski deželi, tako človeka kakor žival in zoper vse egiptovske bogove bom izvršil sodbo. Jaz sem Gospod.',
        13: 'Kri vam bo za simbol na hišah, kjer ste. Ko zagledam kri, bom šel mimo vas in nadloga ne bo na vas, da vas uniči, ko udarim egiptovsko deželo.',
        14: 'Ta dan vam bo v spomin, in vi ga boste ohranjali kot praznik Gospodu skozi svoje rodove. To praznovanje boste ohranjali kot odredbo na veke.',
        15: 'Sedem dni boste jedli nekvašeni kruh; celo prvi dan boste iz svojih hiš odstranili kvas, kajti kdorkoli jé kvašeni kruh od prvega dne do sedmega dne, bo ta duša iztrebljena iz Izraela.',
        16: 'Na prvi dan bo sveti sklic in na sedmi dan vam bo sveti sklic. V teh ne bo opravljena nobena vrsta dela, razen tega, kar mora vsak človek jesti, samo to lahko delate.',
        17: 'Obeležili boste praznik nekvašenega kruha, kajti na prav isti dan sem vaše vojske privedel iz egiptovske dežele. Zato boste ta dan v svojih rodovih obeleževali kot odredbo na veke.',
        18: 'V prvem mesecu, na štirinajsti dan meseca zvečer, boste jedli nekvašeni kruh do enaindvajsetega dne meseca zvečer.',
        19: 'Sedem dni naj v vaših hišah ne bo najti kvasa, kajti kdorkoli jé to, kar je kvašeno, celo ta duša bo iztrebljena iz Izraelove skupnosti, bodisi da je tujec ali rojen v deželi.',
        20: 'Ničesar kvašenega ne boste jedli. V vseh svojih prebivališčih boste jedli nekvašeni kruh.«',
        21: 'Potem je Mojzes dal poklicati vse Izraelove starešine in jim rekel: »Izberite in vzemite si jagnje glede na svoje družine in zakoljite pashalno jagnje.',
        22: 'Vzeli boste šop izopa in ga pomočili v kri, ki je v umivalniku in vratno preklado ter dva podboja premazali s krvjo, ki je v umivalniku; in nihče izmed vas do jutra ne bo šel ven pri vratih svoje hiše.',
        23: 'Kajti Gospod bo šel skozi, da udari Egipčane in ko na vratni prekladi in dveh stranskih podbojih zagleda kri, bo Gospod šel mimo vrat in ne bo dopustil, da bi pokončevalec vstopil v vaše hiše, da vas udari.',
        24: 'Vi pa boste to stvar obeležili kot odredbo sebi in svojim sinovom na veke.',
        25: 'In zgodilo se bo, ko boste prišli v deželo, ki vam jo bo dal Gospod, glede [na to], kar je obljubil, da boste ohranjali to službo.',
        26: 'Zgodilo se bo, ko vam bodo vaši otroci rekli: ›Kaj nameravate s tem služenjem?‹',
        27: 'da boste rekli: ›To je klavna daritev pashe Gospodu, ki je v Egiptu šel mimo hiš Izraelovih otrok, ko je udaril Egipčane in rešil naše hiše.‹« In ljudstvo je sklonilo glavo ter oboževalo.',
        28: 'Izraelovi otroci so odšli in storili, kakor je Gospod zapovedal Mojzesu in Aronu, tako so storili.',
        29: 'Pripetilo se je, da je ob polnoči Gospod udaril vse prvorojeno v egiptovski deželi, od faraonovega prvorojenca, ki je sedel na njegovem prestolu, do ujetnikovega prvorojenca, ki je bil v grajski ječi in vse prvorojeno od živine.',
        30: 'Faraon je ponoči vstal, on in vsi njegovi služabniki in vsi Egipčani in v Egiptu je bilo veliko vpitje, kajti ni bilo hiše, kjer ni bi bilo enega mrtvega.',
        31: 'Ponoči je dal poklicati Mojzesa in Arona ter rekel: »Vstanite in odpravite se proč izmed mojega ljudstva, tako vidva kakor Izraelovi otroci in pojdite, služite Gospodu, kakor sta rekla.',
        32: 'Prav tako vzemite vaše trope in vaše črede, kakor sta rekla in izginite; in tudi mene blagoslovita.«',
        33: 'Egipčani so pritiskali na ljudstvo, da bi jih lahko v naglici odposlali iz dežele, kajti rekli so: »Mi vsi bomo mrtvi ljudje.«',
        34: 'Ljudstvo je vzelo svoje testo, preden je bilo to vzhajano in svoje nečke, ki so bile povezane v njihovih oblačilih, na svoje rame.',
        35: 'Izraelovi otroci so storili glede na Mojzesovo besedo in od Egipčanov so si izposodili dragocenosti iz srebra in dragocenosti iz zlata in oblačil.',
        36: 'In Gospod je dal ljudstvu naklonjenost v očeh Egipčanov, tako da so jim posodili takšne stvari, kot so jih zahtevali. In oplenili so Egipčane.',
        37: '§ Izraelovi otroci so potovali od Ramesésa do Sukóta, okoli šeststo tisoč pešcev, ki so bili možje, poleg otrok.',
        38: 'Z njimi je odšla gor tudi mešana množica, tropi in črede, zelo veliko živine.',
        39: 'Iz testa, ki so ga prinesli iz Egipta, so spekli nekvašeni kruh, kajti ni bil še vzhajan, ker so bili sunjeni iz Egipta in niso mogli ostati niti si zase niso pripravili nobenega živeža.',
        40: 'Torej začasno bivanje Izraelovih otrok, ki so prebivali v Egiptu, je bilo štiristo trideset let.',
        41: 'Ob koncu štiristo tridesetih let se je pripetilo, celo prav na isti dan se je pripetilo, da so vse Gospodove vojske odšle iz egiptovske dežele.',
        42: 'To je noč, ki bo zelo obeleževana Gospodu, ker jih je privedel iz egiptovske dežele. To je tista Gospodova noč, ki jo bodo obeleževali vsi Izraelovi otroci v svojih rodovih.',
        43: 'Gospod je rekel Mojzesu in Aronu: »To je odredba pashe: ›Naj noben tujec od tega ne jé,',
        44: 'toda vsakogar služabnik, ki je kupljen za denar, ko si ga obrezal, potem bo jedel od tega.',
        45: 'Tuj človek in najeti služabnik ne bosta jedla od tega.',
        46: 'Jedlo se ga bo v eni hiši. Nič od mesa ne boš nosil ven iz hiše niti ne boste prelomili njegove kosti.',
        47: 'Vsa Izraelova skupnost se bo tega držala.',
        48: 'Ko bo tujec začasno prebival s teboj in bo praznoval pasho Gospodu, naj bodo vsi njegovi moški obrezani in takrat pustite, da pride blizu in se tega drži, in on naj vam bo kakor nekdo, ki je rojen v deželi, kajti nobena neobrezana oseba ne bo jedla od tega.',
        49: 'Ena postava bo tistemu, ki je rojen doma in tujcu, ki začasno biva med vami.‹«',
        50: 'Tako so storili vsi Izraelovi otroci; kakor je Gospod zapovedal Mojzesu in Aronu, tako so storili.',
        51: 'Na prav isti dan se je pripetilo, da je Gospod privedel Izraelove otroke po njihovih vojskah iz egiptovske dežele.',
    },
    13: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Posvéti mi vse prvorojeno, karkoli odpre maternico med Izraelovimi otroki, tako od ljudi in od živali. To je moje.«',
        3: 'Mojzes je rekel ljudstvu: »Spominjajte se tega dne, na katerega ste prišli iz Egipta, iz hiše sužnosti; kajti z močjo roke vas je Gospod privedel iz tega kraja. Tam se ne bo jedlo nič kvašenega kruha.',
        4: 'Ta dan ste prišli ven v mesecu abíbu.',
        5: 'Zgodilo se bo, ko vas bo Gospod privedel v deželo Kánaancev, Hetejcev, Amoréjcev, Hivéjcev in Jebusejcev, ki jo je prisegel vašim očetom, da vam jo da, deželo, kjer tečeta mleko in med, da se boš v tem mesecu držal te službe.',
        6: 'Sedem dni boš jedel nekvašeni kruh in na sedmi dan bo praznik Gospodu.',
        7: 'Nekvašeni kruh se bo jedel sedem dni in tam pri tebi naj ne bo videti nobenega kvašenega kruha niti ne bo kvasa s teboj v vseh tvojih četrtih.',
        8: 'Tistega dne boš svojemu sinu pokazal, rekoč: › To je storjeno zaradi tega, kar mi je storil Gospod, ko sem izšel iz Egipta.‹',
        9: 'To ti bo za znamenje na tvoji roki in za spomin med tvojimi očmi, da bo lahko Gospodova postava v tvojih ustih, kajti z močno roko te je Gospod privedel iz Egipta.',
        10: 'Držal se boš torej te odredbe v njenem času iz leta v leto.',
        11: 'Zgodilo se bo, ko te bo Gospod pripeljal v deželo Kánaancev, kakor je prisegel tebi in tvojim očetom in ti jo bo dal,',
        12: 'da boš oddvojil Gospodu vse, kar odpre maternico in vsak prvenec, ki pride iz živali, ki jo imaš; samci bodo Gospodovi.',
        13: 'Vsakega prvenca osla pa boš odkupil z jagnjetom. Če pa ga ne boš odkupil, potem mu boš zlomil tilnik. Med svojimi otroki boš odkupil vsakega moškega prvorojenca.',
        14: 'Zgodilo se bo, ko te tvoj sin vpraša, v času, ki pride, rekoč: ›Kaj je to?‹ da mu boš rekel: ›Z močjo roke nas je Gospod privedel iz Egipta, iz hiše sužnosti.',
        15: 'Pripetilo se je, ko nas je faraon komajda odpustil, da je Gospod usmrtil vse prvorojene v egiptovski deželi, tako prvorojene od človeka, kakor prvorojene od živali.‹ Zato žrtvujem Gospodu vse, kar odpre maternico in so samci. Toda vse prvorojene izmed svojih otrok odkupim.',
        16: 'To bo za simbol na tvoji roki in za načelek med tvojimi očmi, kajti z močjo roke nas je Gospod privedel iz Egipta.«',
        17: 'Pripetilo se je, ko je faraon ljudstvu pustil oditi, da jih Bog ni vodil po poti dežele Filistejcev, čeprav je bila ta blizu, kajti Bog je rekel: »Da se ne bi morda ljudstvo pokesalo, ko zagleda vojno in se vrnejo v Egipt,«',
        18: '§ ampak je Bog ljudstvo vodil naokoli, po poti divjine Rdečega morja in Izraelovi otroci so se postrojeni dvignili iz egiptovske dežele.',
        19: 'Mojzes je s seboj vzel Jožefove kosti, kajti ta je strogo zaprisegel Izraelove otroke, rekoč: »Bog vas bo zagotovo obiskal; in vi boste s seboj odnesli moje kosti proč od tod.«',
        20: 'In napotili so se na svoje potovanje iz Sukóta in se utaborili v Etámu, na robu divjine.',
        21: 'In Gospod je hodil podnevi pred njimi v oblačnem stebru, da jih vodi po poti, ponoči pa v ognjenem stebru, da jim daje svetlobo, da bi hodili podnevi in ponoči.',
        22: 'Izpred ljudstva ni vzel proč oblačnega stebra podnevi niti ognjenega stebra ponoči.',
    },
    14: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Govori Izraelovim otrokom, da se obrnejo in se utaborijo pred Pi Hahirótom, med Migdólom in morjem, nasproti Báal Cefónu. Pred njim se boste utaborili ob morju.',
        3: 'Kajti faraon bo o Izraelovih otrocih rekel: ›Zapletli so se v deželi, divjina jih je zaprla noter.‹',
        4: 'Jaz pa bom zakrknil faraonovo srce, da bo sledil za njimi in počaščen bom na faraonu in na vsej njegovi vojski, da bodo Egipčani lahko spoznali, da jaz sem Gospod.« In tako so storili.',
        5: 'Egiptovskemu kralju je bilo povedano, da je ljudstvo zbežalo. In srce faraona in njegovih služabnikov je bilo obrnjeno zoper ljudstvo in rekli so: »Zakaj smo storili to, da smo pustili Izraela oditi od služenja nam?«',
        6: 'In pripravil je svoj bojni voz in s seboj vzel svoje ljudstvo.',
        7: 'Vzel je šeststo izbranih bojnih voz in vse egiptovske bojne vozove in častnike nad vsakim izmed njih.',
        8: 'Gospod je zakrknil srce faraonu, egiptovskemu kralju in ta je zasledoval Izraelove otroke. Izraelovi otroci pa so izšli z vzdignjeno roko.',
        9: 'Toda Egipčani so jih zasledovali, vsi faraonovi konji in bojni vozovi in njegovi konjeniki in njegova vojska in jih dohiteli ob morju, utaborjene poleg Pi Hahiróta, pred Báal Cefónom.',
        10: 'Ko se je faraon približal, so Izraelovi otroci povzdignili svoje oči in glej, Egipčani so korakali za njimi in bili so boleče prestrašeni in Izraelovi otroci so zavpili h Gospodu.',
        11: 'Mojzesu so rekli: »Ali si nas odpeljal proč, da umremo v divjini, ker ni bilo grobov v Egiptu? Zakaj si tako ravnal z nami, da si nas odvedel iz Egipta?',
        12: 'Mar ni to beseda, ki smo ti jo povedali v Egiptu, rekoč: ›Pusti nas pri miru, da lahko služimo Egipčanom?‹ Kajti za nas bi bilo bolje, da služimo Egipčanom, kakor pa, da bi umrli v divjini.«',
        13: 'Mojzes je ljudstvu rekel: »Ne bojte se, mirno stojte in glejte Gospodovo rešitev duš, ki vam jo bo danes pokazal, kajti Egipčane, ki ste jih videli danes, jih na veke ne boste več videli.',
        14: 'Gospod se bo boril za vas in vi boste ohranili svoj mir.«',
        15: 'Gospod je rekel Mojzesu: »Zakaj vpiješ k meni? Govori Izraelovim otrokom, da gredo naprej.',
        16: 'Toda ti vzdigni svojo palico in iztegni svojo roko nad morje in ga razdeli in Izraelovi otroci bodo šli po suhih tleh skozi sredo morja.',
        17: 'Glej, zakrknil bom srca Egipčanom in oni jim bodo sledili in jaz si bom pridobil čast nad faraonom in nad vso njegovo vojsko, nad njegovimi bojnimi vozovi in nad njegovimi konjeniki.',
        18: 'Egipčani bodo vedeli, da jaz sem Gospod, ko sem si pridobil čast nad faraonom, nad njegovimi bojnimi vozovi in nad njegovimi konjeniki.«',
        19: 'Božji angel, ki je šel pred Izraelovim taborom, se je odstranil in odšel za njimi, in oblačni steber je odšel izpred njihovih obrazov in stal za njimi.',
        20: '§ Prišel je med tabor Egipčanov in tabor Izraela. Njim je bil oblak in tema, toda le-tem je dajal svetlobo ponoči, tako da vso noč eni niso prišli blizu k drugim.',
        21: 'Mojzes je svojo roko iztegnil nad morje in Gospod je storil, da je morje vso tisto noč šlo nazaj z močnim vzhodnikom in naredilo morje kopno zemljo in vode so bile razdeljene.',
        22: 'In Izraelovi otroci so šli v sredo morja po suhih tleh in vode so jim bile zid na njihovi desnici in na njihovi levici.',
        23: 'Egipčani pa so jih zasledovali in šli noter za njimi v sredo morja, celo vsi faraonovi konji, njegovi bojni vozovi in njegovi konjeniki.',
        24: 'Pripetilo se je, da je ob jutranji straži Gospod skozi ognjen in oblačen steber pogledal na vojsko Egipčanov in prizadel vojsko Egipčanov.',
        25: '§ Snemal je kolesa njihovim bojnim vozovom, da so jih težko vozili. Tako da so Egipčani rekli: »Zbežimo pred obličjem Izraela, kajti Gospod se bori zanje zoper Egipčane.«',
        26: 'Gospod je rekel Mojzesu: »Svojo roko iztegni nad morje, da lahko vode ponovno pridejo nad Egipčane, nad njihove bojne vozove in nad njihove konjenike.«',
        27: '§ Mojzes je svojo roko iztegnil nad morje in ko se je prikazalo jutro, se je morje vrnilo k svoji moči in Egipčani so bežali proti le-temu; in Gospod je Egipčane porazil v sredi morja.',
        28: 'Vode so se vrnile in pokrile bojne vozove, konjenike in vso faraonovo vojsko, ki je za njimi prišla v morje. Tam ni ostal niti eden izmed njih.',
        29: 'Toda Izraelovi otroci so hodili po suhi zemlji v sredi morja. Vode so jim bile zid na njihovi desnici in na njihovi levici.',
        30: 'Tako je Gospod tega dne rešil Izraela iz roke Egipčanov, in Izrael je videl Egipčane mrtve na morski obali.',
        31: 'Izrael je videl to veliko delo, ki ga je Gospod storil na Egipčanih, in ljudstvo se je balo Gospoda in verjelo Gospodu in njegovemu služabniku Mojzesu.',
    },
    15: {
        1: 'Potem so Mojzes in Izraelovi otroci peli Gospodu tole pesem in govorili, rekoč: »Prepeval bom Gospodu, kajti sijajno je zmagal. Konja in njegovega jezdeca je vrgel v morje.',
        2: 'Gospod je moja moč in pesem in postal je rešitev moje duše. On je moj Bog in pripravil mu bom prebivališče; Bog mojega očeta in poviševal ga bom.',
        3: 'Gospod je bojevnik. Gospod je njegovo ime.',
        4: 'Faraonove vozove in njegovo vojsko je vrgel v morje. Tudi njegovi izbrani častniki so se utopili v Rdečem morju.',
        5: 'Globine so jih pokrile. Na dno so potonili kakor kamen.',
        6: 'Tvoja desnica, oh Gospod, je postala veličastna v oblasti. Tvoja desnica, oh Gospod, je sovražnika razbila na koščke.',
        7: 'V veličini svoje odličnosti si premagal tiste, ki so se vzdignili zoper tebe. Ti pošiljaš svoj bes, ki jih je použil kakor strnišče.',
        8: 'S sunkom vetra tvojih nosnic so bile vode zbrane skupaj, poplave so stale pokončno kakor kup in globine so bile strjene v srcu morja.',
        9: 'Sovražnik je rekel: ›Zasledoval bom, dohitel bom, razdelil bom ukradeno blago. Moje poželenje bo zadovoljeno nad njimi. Izvlekel bom svoj meč, moja roka jih bo uničila.‹',
        10: 'Zapihal si s svojim vetrom, morje jih je pokrilo. Potonili so kakor svinec v mogočnih vodah.',
        11: 'Kdo je podoben tebi, oh Gospod, med bogovi? Kdo je podoben tebi, veličasten v svetosti, strašen v hvalah, ki delaš čudeže?',
        12: 'Izteguješ svojo desnico, zemlja jih je požrla.',
        13: 'V svojem usmiljenju si vodil svoje ljudstvo, ki si ga odkupil. V svoji moči si jih vodil k svojemu svetemu prebivališču.',
        14: '§ Ljudstvo bo slišalo in bo prestrašeno. Bridkost se bo polastila filistejskih prebivalcev.',
        15: 'Potem bodo edómski vojvode osupli; mogočni možje Moába, polastilo se jih bo trepetanje; vsi prebivalci Kánaana se bodo stopili.',
        16: 'Strah in groza bosta padla nanje. Z veličino tvojega lakta bodo tako mirni kakor kamen, dokler tvoje ljudstvo ne gre mimo, oh Gospod, dokler ne gre mimo ljudstvo, ki si ga ti odkupil.',
        17: 'Privedel jih boš noter in jih zasadil na gori svoje dediščine, na kraju, oh Gospod, ki si ga ti naredil zase, da v njem prebivaš, v Svetišču, oh Gospod, ki so ga tvoje roke osnovale.',
        18: 'Gospod bo kraljeval na veke vekov.«',
        19: 'Kajti faraonov konj je šel noter v morje s svojimi bojnimi vozovi in s svojimi konjeniki in Gospod je nadnje ponovno privedel morske vode, toda Izraelovi otroci so šli po suhi zemlji sredi morja.',
        20: 'Mirjam, prerokinja, Aronova sestra, je v svojo roko vzela tamburin in vse ženske so za njo odšle ven s tamburini in s plesi.',
        21: 'Mirjam jim je odgovorila: »Prepevajte Gospodu, kajti sijajno je zmagal; konja in njegovega jezdeca je vrgel v morje.«',
        22: '§ Tako je Mojzes privedel Izraela od Rdečega morja in šli so ven v divjino Šur, in šli so tri dni v divjino, pa niso našli nobene vode.',
        23: 'Ko so prišli do Mare, niso mogli piti od vodá Mare, kajti bile so grenke. Zato je bilo njeno ime imenovano Mara.',
        24: 'Ljudstvo je godrnjalo zoper Mojzesa, rekoč: »Kaj bomo pili?«',
        25: 'In klical je h Gospodu in Gospod mu je pokazal les. Ko je le-tega vrgel v vode, so vode postale sladke. Tam je zanje naredil zakon in odredbo in tam jih je preizkusil',
        26: 'in rekel: »Če boš pazljivo prisluhnil glasu Gospoda, svojega Boga in boš delal to, kar je pravilno v njegovem pogledu in boš prisluhnil njegovim zapovedim in se držal vseh njegovih zakonov, ne bom položil nate nobene od teh bolezni, ki sem jih privedel nad Egipčane, kajti jaz sem Gospod, ki te ozdravlja.«',
        27: 'In prišli so do Elíma, kjer je bilo dvanajst vodnjakov vode in sedemdeset palm, in tam so se utaborili ob vodah.',
    },
    16: {
        1: 'Odšli so na svoje potovanje od Elíma in vsa skupnost Izraelovih otrok je prišla v Sinsko divjino, ki je med Elímom in Sinajem, na petnajsti dan drugega meseca po njihovem odhodu iz egiptovske dežele.',
        2: 'Celotna skupnost Izraelovih otrok je v divjini godrnjala zoper Mojzesa in Arona',
        3: 'in Izraelovi otroci so jima rekli: »Bog daj, da bi umrli po Gospodovi roki v egiptovski deželi, ko smo sedeli pri loncih mesa in ko smo jedli kruha do sitega, kajti privedla sta nas v to divjino, da ta celoten zbor ubijeta z lakoto.«',
        4: 'Potem je Gospod rekel Mojzesu: »Glej, za vas bom z neba deževal kruh in ljudstvo bo šlo ven in vsak dan nabralo določeno mero, da jih lahko preizkusim, ali se bodo ravnali po moji postavi ali ne.',
        5: 'In zgodilo se bo, da bodo na šesti dan pripravili to, kar so prinesli in tega bo dvakrat toliko, kolikor so dnevno nabrali.«',
        6: 'Mojzes in Aron sta vsem Izraelovim otrokom rekla: »Zvečer, takrat boste vedeli, da vas je Gospod izpeljal iz egiptovske dežele',
        7: 'in zjutraj, potem boste videli Gospodovo slavo, kajti on posluša vaša mrmranja zoper Gospoda. Kaj pa sva midva, da mrmrate zoper naju?«',
        8: 'Mojzes je rekel: » To se bo zgodilo, ko vam bo Gospod zvečer dal za jesti meso in zjutraj kruha do sitega, zakaj Gospod sliši vaša mrmranja, ki jih mrmrate zoper njega. Kaj pa sva midva? Vaša mrmranja niso zoper naju, temveč zoper Gospoda.«',
        9: 'Mojzes je spregovoril Aronu: »Povej vsej skupnosti Izraelovih otrok: ›Pridite bliže, pred Gospoda, kajti slišal je vaša mrmranja.‹«',
        10: 'Pripetilo se je, ko je Aron govoril celotni skupnosti Izraelovih otrok, da so pogledali proti divjini in glej, Gospodova slava se je prikazala v oblaku.',
        11: 'Gospod je spregovoril Mojzesu, rekoč:',
        12: '»Slišal sem mrmranja Izraelovih otrok. Govori jim, rekoč: ›Zvečer boste jedli meso in zjutraj boste nasičeni s kruhom in vedeli boste, da jaz sem Gospod, vaš Bog.‹«',
        13: 'Pripetilo se je, da so se zvečer pojavile prepelice in pokrile tabor in zjutraj je rosa ležala naokoli vojske.',
        14: 'Ko je rosa, ki je ležala, izparela, glej, na obličju divjine je ležala majhna okrogla stvar, tako majhna kakor slana na tleh.',
        15: '§ Ko so Izraelovi otroci to zagledali, so drug drugemu rekli: »To je mana.« Kajti niso vedeli, kaj je bilo to. Mojzes pa jim je rekel: »To je kruh, ki vam ga Gospod daje za jesti.',
        16: 'To je stvar, ki jo je Gospod zapovedal: ›Vsak mož naj od tega nabere glede na svoje prehranjevanje, gomer za vsakega človeka, glede na število vaših oseb; vzemite vsak mož za tiste, ki so v njegovih šotorih.‹«',
        17: 'Izraelovi otroci so storili tako in nabrali, nekateri več, drugi manj.',
        18: 'Ko so to izmerili z gomerjem, kdor je nabral veliko, ni imel preveč in kdor je nabral malo, ni imel pomanjkanja. Vsak človek je nabral glede na svoje prehranjevanje.',
        19: 'Mojzes je rekel: »Naj noben človek od tega ne pusti do jutra.«',
        20: 'Vendar niso poslušali Mojzesa, temveč so nekateri izmed njih pustili od tega do jutra in zaredile so se ličinke ter smrad in Mojzes je bil nad njimi ogorčen.',
        21: 'To so nabirali vsako jutro, vsak človek glede na svoje prehranjevanje. Ko pa je sonce postalo vroče, se je stopilo.',
        22: 'Pripetilo se je, da so na šesti dan nabrali dvakrat toliko kruha, dva gomerja za enega človeka, in prišli so vsi voditelji skupnosti ter povedali Mojzesu.',
        23: 'Rekel jim je: »To je to, kar je rekel Gospod: ›Jutri je počitek svetega šabata Gospodu. To, kar boste spekli, specite danes in zavrite to, kar boste vreli. To pa, kar preostane, vzemite iz uporabe, da bo obdržano do jutra.‹«',
        24: 'In to so vzeli iz uporabe do jutra, kakor je Mojzes zaukazal, in to ni zaudarjalo niti v tem ni bilo nobenih ličink.',
        25: 'Mojzes je rekel: »To jejte danes, kajti danes je šabat Gospodu. Danes tega ne boste našli na polju.',
        26: 'Šest dni boste to nabirali, toda na sedmi dan, ki je šabat, ne bo ničesar.«',
        27: 'Pripetilo se je, da je nekaj ljudi izmed ljudstva na sedmi dan odšlo, da nabirajo, pa niso našli ničesar.',
        28: 'Gospod je rekel Mojzesu: »Doklej boste odklanjali, da se držite mojih zapovedi in mojih postav?',
        29: 'Poglejte, zakaj Gospod vam je dal šabat, zato vam na šesti dan daje kruh dveh dni. Vsak človek naj ostane na svojem kraju, naj noben človek na sedmi dan ne gre iz svojega kraja.«',
        30: 'Tako je ljudstvo na sedmi dan počivalo.',
        31: 'Izraelova hiša je njeno ime imenovala Mana, in ta je bila podobna koriandrovemu semenu, bela, in njen okus je bil podoben vafljem, narejenim z medom.',
        32: 'Mojzes je rekel: »To je stvar, ki jo je Gospod zapovedal: ›S tem napolnite gomer, da bo obdržano za vaše rodove, da bodo lahko videli kruh, s katerim sem vas hranil v divjini, ko sem vas izpeljal iz egiptovske dežele.‹«',
        33: 'Mojzes je Aronu rekel: »Vzemi lonec in vanj stresi gomer, poln mane in ga položi pred Gospoda, da bo obdržan za vaše rodove.«',
        34: 'Kakor je Gospod zapovedal Mojzesu, tako je Aron to položil pred Pričevanje, da bo obdržano.',
        35: 'Izraelovi otroci so štirideset let jedli mano, dokler niso prišli v naseljeno deželo. Jedli so mano, dokler niso prišli do meja kánaanske dežele.',
        36: 'Torej gomer je desetina škafa.',
    },
    17: {
        1: 'Vsa skupnost Izraelovih otrok je odpotovala iz Sinske divjine, po njihovih potovanjih, glede na Gospodovo zapoved in utaborili so se v Refidímu. Tam pa ni bilo nobene vode, da bi ljudstvo pilo.',
        2: 'Zakaj ljudstvo se je pričkalo z Mojzesom in govorilo: »Daj nam vode, da lahko pijemo.« Mojzes pa jim je rekel: »Zakaj se pričkate z menoj? Zakaj skušate Gospoda?«',
        3: 'Ljudstvo pa je hlepelo po vodi in ljudstvo je mrmralo zoper Mojzesa ter reklo: »Zakaj je to, da si nas izpeljal iz Egipta, da z žejo ubiješ nas, naše otroke in našo živino?«',
        4: 'Mojzes je vpil h Gospodu, rekoč: »Kaj naj storim temu ljudstvu? Skoraj so pripravljeni, da me kamnajo.«',
        5: 'Gospod je rekel Mojzesu: »Pojdi naprej pred ljudstvom in s seboj vzemi Izraelove starešine, in svojo palico, s katero si udaril reko, vzemi v svojo roko in pojdi.',
        6: 'Glej, stal bom pred teboj, tam na skali na Horebu, ti pa boš udaril skalo in iz nje bo pritekla voda, da bo ljudstvo lahko pilo.« In Mojzes je tako storil v očeh Izraelovih starešin.',
        7: 'Ime kraja je imenoval Masa in Meríba, zaradi pričkanja Izraelovih otrok in ker so skušali Gospoda, rekoč: »Je Gospod med nami ali ni?«',
        8: 'Potem je prišel Amálek in se z Izraelom bojeval v Refidímu.',
        9: 'Mojzes je rekel Józuetu: »Izmed nas izberi može in pojdite ven in se bojujte z Amálekom. Jutri bom stal na vrhu hriba z Božjo palico v svoji roki.«',
        10: 'Józue je storil tako, kakor mu je rekel Mojzes in se bojeval z Amálekom. Mojzes, Aron in Hur pa so odšli na vrh hriba.',
        11: 'Pripetilo se je, ko je Mojzes držal svojo roko pokonci, da je prevladoval Izrael. Ko pa je svojo roko spustil, je prevladoval Amálek.',
        12: 'Vendar pa sta bili Mojzesovi roki težki. Vzela sta kamen in ga položila pod njega in sedel je nanj. Aron in Hur pa sta opirala njegovi roki, eden na eni strani, drugi pa na drugi strani, in njegovi roki sta bili stabilni do sončnega zahoda.',
        13: 'In Józue je z ostrino meča porazil Amáleka in njegovo ljudstvo.',
        14: 'Gospod je rekel Mojzesu: »Zapiši to za spomin v knjigo in to ponovi v Józuetova ušesa, kajti jaz bom popolnoma izbrisal spomin na Amáleka izpod neba.«',
        15: '§ Mojzes je zgradil oltar in njegovo ime imenoval JAHVE–nisi,',
        16: 'kajti rekel je: »Ker je Gospod prisegel, da bo imel Gospod vojno z Amálekom od roda do roda.«',
    },
    18: {
        1: 'Ko je Jitro, midjánski duhovnik, Mojzesov tast, slišal o vsem, kar je Bog storil za Mojzesa in za svoje ljudstvo Izraela in da je Gospod Izraela privedel iz Egipta,',
        2: 'je potem Mojzesov tast Jitro vzel Mojzesovo ženo Cipóro, potem ko jo je ta poslal nazaj',
        3: 'in njena dva sinova, od katerih je bilo enemu ime Geršóm; kajti rekel je: »Neznanec sem bil v tuji deželi,«',
        4: 'ime drugega pa je bilo Eliézer; kajti: »Bog mojega očeta,« je rekel, »je bil moja pomoč in me osvobodil pred faraonovim mečem.«',
        5: 'Mojzesov tast Jitro je prišel, z njegovima sinovoma in njegovo ženo, k Mojzesu v divjino, kjer je bil utaborjen pri gori Boga',
        6: 'in Mojzesu je rekel: »Jaz, tvoj tast Jitro, sem prišel k tebi in tvoja žena in njena dva sinova z njo.«',
        7: 'Mojzes je odšel ven, da sreča svojega tasta in se globoko priklonil ter ga poljubil. Drug drugega sta vprašala o njuni blaginji in prišla v šotor.',
        8: 'Mojzes je svojemu tastu povedal vse, kar je zaradi Izraela Gospod storil faraonu in Egipčanom in vse muke, ki so prišle nadnje na poti in kako jih je Gospod osvobodil.',
        9: 'Jitro se je razveselil zaradi vse dobrote, ki jo je Gospod storil Izraelu, ki ga je osvobodil iz roke Egipčanov.',
        10: 'Jitro je rekel: »Blagoslovljen bodi Gospod, ki vas je osvobodil iz roke Egipčanov in iz roke faraona, ki je ljudstvo osvobodil izpod roke Egipčanov.',
        11: 'Sedaj vem, da je Gospod večji od vseh bogov, kajti v stvari, v kateri so oni ponosno postopali, je bil on nad njimi.«',
        12: 'Mojzesov tast Jitro, je vzel žgalno daritev, klavne daritve za Boga in prišel je Aron ter vse Izraelove starešine, da z Mojzesovim tastom jedo kruh pred Bogom.',
        13: 'In pripetilo se je naslednji dan, da se je Mojzes usedel, da sodi ljudstvu in ljudstvo je stalo pri Mojzesu od jutra do večera.',
        14: 'Ko je Mojzesov tast videl vse to, kar je počel ljudstvu, je rekel: »Kaj je ta stvar, ki jo počneš ljudstvu? Zakaj ti sam sediš, vse ljudstvo pa stoji pri tebi od jutra do večera?«',
        15: 'Mojzes je svojemu tastu rekel: »Ker ljudstvo prihaja k meni, da povprašuje od Boga.',
        16: 'Kadar imajo zadevo, pridejo k meni in jaz sodim med enim in drugim in jaz jim dam spoznavati zakone Boga in njegove postave.«',
        17: 'Mojzesov tast pa mu je rekel: »Stvar, ki jo počneš, ni dobra.',
        18: 'Zagotovo se boš izčrpal, tako ti in to ljudstvo, ki je s teboj, kajti ta stvar je zate pretežka; ti tega nisi zmožen opravljati sam.',
        19: 'Prisluhni torej mojemu glasu, dal ti bom nasvet in Bog bo s teboj: ›Ti bodi za ljudstvo usmerjen k Bogu, da boš zadeve lahko prinašal k Bogu.',
        20: 'Učil jih boš odredbe in postave in kazal jim boš pot, po kateri morajo hoditi in delo, ki ga morajo opraviti.',
        21: 'Poleg tega boš izmed vsega ljudstva priskrbel sposobne može, takšne, ki se bojijo Boga, može resnice, ki sovražijo pohlepnost. Nad njimi postavi takšne, da bodo vodje nad tisočimi in vodje nad stotimi, vodje nad petdesetimi in vodje nad desetimi.',
        22: 'Ti naj sodijo ljudstvu v vseh obdobjih in zgodilo se bo, da se bo vsaka velika zadeva prinesla predte, toda vsako majhno zadevo bodo sodili oni. Tako bo zate lažje, oni pa bodo breme nosili s teboj.',
        23: 'Če boš storil to stvar in ti Bog tako zapove, potem boš zmožen vzdržati in tudi vse to ljudstvo bo v miru hodilo k svojemu kraju.‹«',
        24: 'Tako je Mojzes prisluhnil glasu svojega tasta in storil vse, kar je ta rekel.',
        25: 'Mojzes je izbral sposobne može iz vsega Izraela in jih naredil poglavarje nad ljudstvom, vodje nad tisočimi, vodje nad stotimi, vodje nad petdesetimi in vodje nad desetimi.',
        26: 'Sodili so ljudstvu v vseh obdobjih. Težje stvari so prinašali k Mojzesu, toda vsako majhno zadevo so sodili sami.',
        27: 'In Mojzes je pustil svojemu tastu oditi in ta je odšel svojo pot v svojo lastno deželo.',
    },
    19: {
        1: 'V tretjem mesecu, ko so Izraelovi otroci odšli iz egiptovske dežele, istega dne, so prišli v Sinajsko divjino.',
        2: 'Kajti odšli so iz Refidíma in prišli v sinajsko puščavo in se utaborili v divjini in tam je Izrael taboril pred goro.',
        3: 'Mojzes je odšel gor k Bogu in Gospod je zaklical k njemu z gore, rekoč: »Tako boš rekel Jakobovi hiši in povedal Izraelovim otrokom:',
        4: '›Videli ste, kaj sem storil Egipčanom in kako sem vas nosil na orljih perutih in vas privedel k sebi.',
        5: 'Zdaj torej, če boste zares poslušali moj glas in se držali moje zaveze, potem mi boste izvoljen zaklad nad vsemi ljudstvi, kajti vsa zemlja je moja,',
        6: 'vi pa mi boste kraljestvo duhovnikov in svet narod.‹ To so besede, ki jih boš govoril Izraelovim otrokom.«',
        7: 'Mojzes je prišel ter dal poklicati starešine ljudstva in pred njihove obraze položil vse te besede, ki mu jih je Gospod zapovedal.',
        8: 'Vse ljudstvo je skupaj odgovorilo ter reklo: »Vse, kar je Gospod govoril, bomo storili.« In Mojzes je besede ljudstva ponovil Gospodu.',
        9: 'Gospod je rekel Mojzesu: »Glej, k tebi pridem v gostem oblaku, da bo ljudstvo lahko slišalo, ko govorim s teboj in ti verjelo na veke.« In Mojzes je besede ljudstva povedal Gospodu.',
        10: 'Gospod je rekel Mojzesu: »Pojdi k ljudstvu in posvečuj jih danes in jutri in naj si operejo svoja oblačila',
        11: 'in bodite pripravljeni za tretji dan, kajti tretji dan bo Gospod prišel dol, v očeh vsega ljudstva, na goro Sinaj.',
        12: 'Ti pa boš ljudstvu postavil meje naokoli, rekoč: ›Pazite se, da ne greste gor na goro ali se dotaknete njene meje. Kdorkoli se dotakne gore, bo zagotovo usmrčen.',
        13: 'Niti roka se ga ne bo dotaknila, temveč naj bo zagotovo kamnan ali prestreljen; bodisi bo to žival ali človek, naj ta ne živi. Ko zadoni trobljenje naj pridejo h gori.‹«',
        14: 'Mojzes je odšel dol z gore k ljudstvu in ljudstvo posvetil, in ti so si oprali svoja oblačila.',
        15: 'Ljudstvu je rekel: »Bodite pripravljeni na tretji dan. Ne približujte se k svojim ženam.«',
        16: 'Na tretji dan se je zjutraj pripetilo, da so bila grmenja in bliski in na gori gost oblak in silno glasen zvok šofarja, tako da je vse ljudstvo, ki je bilo v taboru, trepetalo.',
        17: 'Mojzes je ljudstvo privedel iz tabora, da se sreča z Bogom. Stali so pri spodnjem delu gore.',
        18: 'Gora Sinaj je bila povsem v dimu, ker se je Gospod nanjo spustil v ognju in njen dim se je vzpenjal kakor dim iz talilne peči in celotna gora se je silno tresla.',
        19: 'Ko je glas šofarja zategnjeno donel in postajal glasnejši in glasnejši, je Mojzes spregovoril in Bog mu je odgovoril z glasom.',
        20: 'Gospod je prišel dol na goro Sinaj, na vrh gore in Gospod je Mojzesa poklical gor na vrh gore in Mojzes je odšel gor.',
        21: 'Gospod je rekel Mojzesu: »Pojdi dol, naroči ljudstvu, da se ne bi prebili h Gospodu, da bi strmeli in se mnogi izmed njih pogubijo.',
        22: 'Naj se tudi duhovniki, ki pridejo bliže h Gospodu, posvétijo, da ne bi Gospod izbruhnil nad njimi.«',
        23: 'Mojzes pa je rekel Gospodu: »Ljudstvo se ne more povzpeti na goro Sinaj, kajti zapovedal si nam, rekoč: ›Postavi meje okoli gore in jo posvéti.‹«',
        24: 'Gospod mu je rekel: »Proč, spusti se in prišel boš gor, ti in Aron s teboj. Toda duhovniki in ljudstvo naj se ne prebijejo, da pridejo h Gospodu, da ne bi nad njimi izbruhnil.«',
        25: 'Tako je Mojzes odšel dol k ljudstvu in jim spregovoril.',
    },
    20: {
        1: 'Bog je spregovoril vse te besede, rekoč:',
        2: '[1] »Jaz sem Gospod, tvoj Bog, ki sem te privedel iz egiptovske dežele, iz hiše sužnosti.',
        3: '[2] Pred menoj ne boš imel nobenih drugih bogov.',
        4: 'Sebi ne boš naredil nobene rezane podobe ali kakršnekoli podobnosti čemurkoli, kar je zgoraj na nebu ali kar je spodaj na zemlji ali kar je v vodi pod zemljo.',
        5: 'Ne boš se jim priklanjal niti jim ne boš služil, kajti jaz, Gospod, tvoj Bog, sem ljubosumen Bog, ki obiskujem krivičnost očetov na otrocih do tretjega in četrtega rodu tistih, ki me sovražijo,',
        6: 'izkazujem pa usmiljenje tisočem tistih, ki me ljubijo in varujejo moje zapovedi.',
        7: '[3] Ne boš v prazno vzel imena Gospoda, svojega Boga; kajti Gospod ne bo držal brez krivde tistega, ki v prazno jemlje njegovo ime.',
        8: '[4] Spominjaj se šabatnega dne, da ga ohraniš svetega.',
        9: 'Šest dni se boš trudil in opravljal vse svoje delo,',
        10: 'toda sedmi dan je šabat Gospodu, tvojemu Bogu. Na [ta dan] ne boš opravljal nobenega dela, ne ti, niti tvoj sin, niti tvoja hči, [niti] tvoj sluga, niti tvoja dekla, niti tvoja živina, niti tvoj tujec, ki je znotraj tvojih velikih vrat,',
        11: 'kajti v šestih dneh je Gospod naredil nebo in zemljo, morje in vse, kar je v njih, sedmi dan pa je počival. Zato je Gospod blagoslovil šabatni dan in ga posvetil.',
        12: '[5] Spoštuj svojega očeta in svojo mater, da bodo tvoji dnevi lahko dolgi na zemlji, ki ti jo daje Gospod, tvoj Bog.',
        13: '[6] Ne boš ubil.',
        14: '[7] Ne boš zagrešil zakonolomstva.',
        15: '[8] Ne boš kradel.',
        16: '[9] Ne boš prinašal krivega pričevanja zoper svojega bližnjega.',
        17: '[10] Ne boš hlepel [po] hiši svojega bližnjega, ne boš hlepel [po] ženi svojega bližnjega, niti [po] njegovem slugi, niti [po] njegovi dekli, niti [po] njegovem volu, niti [po] njegovem oslu, niti [po] katerikoli stvari, ki je od tvojega bližnjega!«',
        18: 'In vse ljudstvo je videlo grmenja in bliske, zvok šofarja in kadečo goro. Ko je ljudstvo to videlo, so se odstranili in stali daleč stran.',
        19: 'Mojzesu pa so rekli: »Ti govori z nami, mi pa bomo poslušali, toda Bog naj z nami ne govori, da ne bi umrli.«',
        20: 'Mojzes je ljudstvu rekel: »Ne bojte se, kajti Bog je prišel, da vas preizkusi in da je njegov strah lahko pred vašimi obrazi, da ne grešite.«',
        21: '§ Ljudstvo je stalo daleč stran, Mojzes pa se je približal gosti temi, kjer je bil Bog.',
        22: 'Gospod je rekel Mojzesu: »Tako boš rekel Izraelovim otrokom: ›Videli ste, da sem z vami govoril iz nebes.',
        23: 'Poleg mene ne boste delali bogov iz srebra niti si ne boste delali bogov iz zlata.',
        24: '§ Naredil mi boš oltar iz zemlje in na njem boš žrtvoval svoje žgalne daritve in svoje mirovne daritve, svoje ovce in svoje vole. Na vseh krajih, kjer zapišem svoje ime, bom prišel k tebi in te blagoslovil.',
        25: 'Če mi hočeš narediti oltar iz kamna, ga ne boš zgradil iz klesanega kamna, kajti če svoje orodje dvigneš nanj, si ga oskrunil.',
        26: 'Niti k mojemu oltarju ne boš šel gor po stopnicah, da na njih ne bo odkrita tvoja nagota.',
    },
    21: {
        1: 'Torej to so sodbe, ki jih boš postavil prednje.',
        2: 'Če kupiš hebrejskega služabnika, naj ti služi šest let. V sedmem letu pa naj odide prost, brez plačila.',
        3: 'Če je sam prišel, naj sam odide. Če je bil poročen, potem naj njegova žena odide z njim.',
        4: 'Če mu je njegov gospodar dal ženo in mu je rodila sinove ali hčere, naj bodo žena in njeni otroci [od] njegovega gospodarja, on pa naj odide sam.',
        5: 'Če mu bo služabnik jasno rekel: ›Ljubim svojega gospodarja, svojo ženo in svoje otroke; ne bom odšel svoboden,‹',
        6: '§ potem naj ga njegov gospodar privede k sodnikom. Prav tako naj ga privede k vratom ali k podboju in njegov gospodar naj njegovo uho prebode s šilom, on pa naj mu za vedno služi.',
        7: 'Če človek proda svojo hčer, da postane dekla, naj ona ne odide, kakor storijo služabniki.',
        8: 'Če ne ugaja svojemu gospodarju, ki si jo je zaročil, tedaj naj bo odkupljena. Ne bo imel oblasti, da jo proda v tuj narod, glede na to, da je z njo ravnal varljivo.',
        9: 'Če jo je zaročil svojemu sinu, naj z njo postopa po načinu hčera.',
        10: 'Če si vzame drugo ženo, naj njene hrane, njenega oblačila in njene zakonske dolžnosti ne zmanjša.',
        11: 'Če ji ne stori teh treh stvari, potem naj ta odide ven prosta, brez denarja.',
        12: 'Kdor udarja človeka, tako da umre, naj bo zagotovo usmrčen.',
        13: 'Če človek ne preži nanj, temveč ga Bog izroči v njegovo roko, potem bom določil kraj, kamor naj zbeži.',
        14: 'Toda če pride človek prepotentno nad svojega bližnjega, da ga z zvijačo ubije, ga odvedi od mojega oltarja, da lahko umre.',
        15: 'Kdor udarja svojega očeta ali svojo mater, naj bo zagotovo usmrčen.',
        16: 'Kdor ugrabi človeka in ga prodaja ali če je le-ta najden v njegovi roki, naj bo zagotovo usmrčen.',
        17: 'Kdor preklinja svojega očeta ali svojo mater, naj bo zagotovo usmrčen.',
        18: 'Če se moža skupaj prepirata in je eden udaril drugega s kamnom ali s svojo pestjo, pa ta ne umre, temveč se drži svoje postelje;',
        19: '§ če ta ponovno vstane in hodi okoli na svoji palici, potem naj bo tisti, ki ga je udaril, oproščen. Samo plačal mu bo za izgubo njegovega časa in poskrbel bo, da bo temeljito ozdravljen.',
        20: 'Če človek udari svojega služabnika ali svojo služabnico s palico in le-ta pod njegovo roko umre, naj bo zagotovo kaznovan.',
        21: 'Vendar če preživi dan ali dva, naj ne bo kaznovan, kajti on je njegov denar.',
        22: 'Če se moža prepirata in poškodujeta nosečnico, tako da njen sad odide od nje in ne sledi nobena škoda, naj bo ta zagotovo kaznovan glede na to, kakor mu naloži ženin soprog. Plača naj, kakor mu bodo določili sodniki.',
        23: 'Če sledi katerakoli nesreča, potem boš dal življenje za življenje,',
        24: 'oko za oko, zob za zob, roko za roko, stopalo za stopalo,',
        25: '§ opeklino za opeklino, rano za rano, udarec z bičem za udarec z bičem.',
        26: 'Če človek udari oko svojega služabnika ali oko svoje služabnice, da le-ta propade, naj ga pusti oditi svobodnega zaradi njegovega očesa.',
        27: 'Če svojemu slugi izbije zob ali zob svoji dekli, naj ga pusti oditi prostega zaradi njegovega zoba.',
        28: 'Če vol zabode moškega ali žensko, da umreta, potem naj bo vol zagotovo kamnan in njegovo meso naj se ne jé, toda lastnik vola naj bo oproščen.',
        29: 'Toda če je imel vol navado, da je s svojim rogom bodel v preteklem času in je bilo to pričevano njegovemu lastniku, pa ga ta ni držal zaprtega, temveč da je usmrtil moškega ali žensko, naj bo vol kamnan in tudi njegov lastnik naj bo usmrčen.',
        30: 'Če mu bo naložena vsota denarja, potem naj da za odkupnino svojega življenja, karkoli mu bo naloženo.',
        31: 'Če je nabodel sina ali nabodel hčer, naj mu bo storjeno glede na to sodbo.',
        32: 'Če bo vol pobodel sluga ali deklo, naj njihovemu gospodarju da trideset šeklov srebra, vol pa naj bo kamnan.',
        33: 'Če bo človek odprl jamo ali če bo človek izkopal jamo in je ne bo pokril in vanjo pade vol ali osel,',
        34: 'naj lastnik jame to dobro naredi in da denar lastniku le-teh; mrtva žival pa naj bo njegova.',
        35: 'Če pa vol nekega človeka poškoduje drugega, da ta umre, potem naj prodajo živega vola in razdelijo denar od njega; in prav tako naj razdelijo mrtvega vola.',
        36: 'Ali če je bilo znano, da je imel vol navado v preteklem času bosti, pa ga njegov lastnik ni imel zaprtega, naj zagotovo plača vola za vola, mrtvi pa naj bo njegov.',
    },
    22: {
        1: 'Če bo človek ukradel vola ali ovco in to zakolje ali proda, naj povrne pet volov za vola in štiri ovce za ovco.',
        2: 'Če je najden tat, da vlamlja in je udarjen, da umre, potem naj zanj ne bo prelite nobene krvi.',
        3: 'Če je nad njim vstalo sonce, naj bo zanj prelita kri, kajti moral bi narediti popolno povračilo. Če nima ničesar, potem naj bo prodan za svojo tatvino.',
        4: 'Če je tatvina v njegovi roki zagotovo najdena živa, bodisi je to vol ali osel ali ovca, naj povrne dvojno.',
        5: 'Če bo človek polju ali vinogradu povzročil, da bo požrto in bo vanj postavil svojo žival, pa se bo pasla na polju drugega človeka, naj povrne od najboljšega svojega lastnega polja in od najboljšega svojega lastnega vinograda.',
        6: 'Če izbruhne ogenj in zajame trnje, tako da so s tem použite kopice žita ali stoječe žito ali polje, naj tisti, ki je zanetil ogenj, zagotovo naredi povračilo.',
        7: 'Če bo človek izročil svojemu bližnjemu v hrambo denar ali stvari, pa bo to ukradeno iz človekove hiše; če bo tat najden, naj plača dvojno.',
        8: '§ Če tat ne bo najden, potem naj bo gospodar hiše priveden k sodnikom, da vidijo, ali je svojo roko položil na dobrine svojega bližnjega.',
        9: '§ Kajti vse vrste prekrški, bodisi je to za vola, za osla, za ovco, za oblačilo ali za katerokoli vrsto izgubljene stvari, za katero drug zatrjuje, da je njegova, naj zadeva obeh strani pride pred sodnike. In kogar bodo sodniki obsodili, naj svojemu bližnjemu plača dvojno.',
        10: 'Če človek svojemu bližnjemu izroči osla ali vola ali ovco ali katerokoli žival v varstvo, pa ta pogine ali je ranjena ali odpeljana proč [in] noben človek tega ne vidi,',
        11: 'potem naj bo Gospodova prisega med njima obema, da svoje roke ni položil na dobrine svojega bližnjega. Njegov lastnik bo od tega sprejel, oni pa tega ne bo povrnil.',
        12: 'Če je to od njega ukradeno, naj od tega lastniku naredi povračilo.',
        13: 'Če bo to raztrgano na koščke, potem naj to prinese kot pričevanje, on pa ne bo povrnil tega, kar je bilo raztrgano.',
        14: 'Če si človek karkoli izposodi od svojega bližnjega in je to poškodovano ali pogine, pa njegov lastnik ni bil s tem, naj on to zagotovo povrne.',
        15: 'Vendar, če je bil lastnik od tega z njim, naj on tega ne povrne. Če je bila najeta stvar, je ta prišla za njegovo najemnino.',
        16: 'Če mož privabi devico, ki ni zaročena in leži z njo, naj jo zagotovo oskrbi z doto, da postane njegova žena',
        17: 'Če njen oče popolnoma odklanja, da mu jo da, naj plača denar glede na doto devic.',
        18: 'Ne boš trpel, da bi čarovnica živela.',
        19: 'Kdorkoli leži z živaljo, naj bo zagotovo usmrčen.',
        20: 'Kdor žrtvuje kateremukoli bogu, razen samo Gospodu, naj bo popolnoma uničen.',
        21: 'Tujca ne boš niti dražil niti zatiral, kajti tujci ste bili v egiptovski deželi.',
        22: 'Ne boste stiskali katerekoli vdove ali osirotelega otroka.',
        23: 'Če jih boste na kakršen koli način stiskali in oni kakorkoli kličejo k meni, bom zagotovo slišal njihov klic',
        24: 'in moj bes se bo razvnel in ubil vas bom z mečem; in vaše žene bodo vdove in vaši otroci sirote.',
        25: 'Če komurkoli izmed mojega ljudstva, ki je poleg tebe ubog, posodiš denar, do njega ne bodi kakor oderuh niti nanj ne nalagaj obresti.',
        26: 'Če sploh vzameš za jamstvo oblačilo svojega bližnjega, mu ga boš izročil do takrat, ko zahaja sonce.',
        27: 'Kajti to je njegovo edino pokrivalo, to je njegovo oblačilo za njegovo kožo. V čem bo spal? In zgodilo se bo, ko kliče k meni, da bom slišal, kajti jaz sem milostljiv.',
        28: 'Ne boš zasramoval bogov niti preklinjal vladarja svojega ljudstva.',
        29: '§ Ne boš odlašal darovati prvin od svojih zrelih sadov in od svojih žganih pijač. Prvorojenega izmed svojih sinov boš dal meni.',
        30: 'Podobno boš storil s svojimi voli in s svojimi ovcami. Sedem dni naj bo ta s svojo materjo, na osmi dan pa ga boš dal meni.',
        31: 'Vi mi boste sveti ljudje niti ne boste jedli kakršnega koli mesa, ki je raztrgano od živali na polju; vrgli ga boste psom.',
    },
    23: {
        1: 'Ne boš dvignil napačnega poročila. Svoje roke ne podaj z zlobnim, da bi bil nepravična priča.',
        2: '§ Ne boš sledil množici, da počneš zlo. Niti ne boš govoril v zadevi, da se ne nagneš za mnogimi, ki pačijo sodbo.',
        3: 'Niti ne boš podpiral reveža v njegovi zadevi.',
        4: 'Če srečaš vola svojega sovražnika ali njegovega osla zaiti, mu ga boš zagotovo ponovno privedel nazaj k njemu.',
        5: 'Če vidiš osla tistega, ki te sovraži, ležati pod svojim bremenom in odlašaš, da mu pomagaš, mu boš zagotovo z njim vred pomagal.',
        6: 'Ne boš pačil sodbe ubogega v njegovi zadevi.',
        7: 'Drži se proč od napačne stvari. Nedolžnega in pravičnega ne ubij, kajti zlobnega ne bom opravičil.',
        8: '§ In ti ne boš prejel nobenega daru, kajti dar slepi modrega in izkrivlja besede pravičnega.',
        9: '§ Tudi ne boš zatiral tujca, kajti poznate srce tujca, glede na to, da ste bili tujci v egiptovski deželi.',
        10: 'Šest let boš sejal svojo zemljo in zbiral njene sadove,',
        11: 'toda sedmo leto jo boš pustil počivati in mirno ležati, da ubogi izmed tvojega ljudstva lahko jedo. Kar bodo pustili, naj pojedo živali polja. Na podoben način boš postopal s svojim vinogradom in s svojim oljčnim nasadom.',
        12: 'Šest dni boš opravljal svoje delo, na sedmi dan pa boš počival, da bosta tvoj vol in tvoj osel lahko počivala in bosta sin tvoje pomočnice in tujec lahko osvežena.',
        13: 'V vseh stvareh, ki sem ti jih rekel, bodi preudaren. In ne omenjaj imena drugih bogov niti naj tega ne bo slišati iz tvojih ust.',
        14: 'Trikrat v letu mi boš ohranjal praznovanje.',
        15: 'Ohranjal boš praznik nekvašenega kruha (sedem dni boš jedel nekvašeni kruh, kakor sem ti zapovedal, v določenem času meseca abíba, kajti v njem si prišel iz Egipta in nihče se pred menoj ne bo prikazal prazen)',
        16: 'in praznik žetve, prve sadove svojih trudov, ki si jih posejal na polju in praznik spravljanja, ki je ob koncu leta, ko si svoje trude pospravil s polja.',
        17: 'Trikrat na leto naj se vsi tvoji možje prikažejo pred Gospodom Bogom.',
        18: 'Krvi moje klavne daritve ne boš žrtvoval z vzhajanim kruhom niti naj maščoba mojega darovanja ne ostane do jutra.',
        19: 'Prvine od prvih sadov svoje zemlje boš prinesel v hišo Gospoda, svojega Boga. Kozlička ne boš zavrel v mleku njegove matere.',
        20: 'Glej, pred teboj pošiljam Angela, da te varuje na poti in te privede na kraj, ki sem ga pripravil.',
        21: 'Pazi se ga in ubogaj njegov glas, ne izzivaj ga, kajti ne bo oprostil tvojih prestopkov, kajti moje ime je v njem.',
        22: 'Toda če boš zares ubogal njegov glas in storil vse, kar ti govorim, potem bom sovražnik tvojih sovražnikov in nasprotnik tvojih nasprotnikov.',
        23: 'Kajti moj Angel bo šel pred teboj in te privede k Amoréjcem, Hetejcem, Perizéjcem, Kánaancem, Hivéjcem in Jebusejcem, in jaz jih bom odrezal.',
        24: 'Ne boš se priklanjal njihovim bogovom niti jim služil niti počel po njihovih delih, temveč jih boš popolnoma premagal in popolnoma zlomil njihove podobe.',
        25: 'Služili boste Gospodu, svojemu Bogu in on bo blagoslovil tvoj kruh in tvojo vodo, in iz tvoje srede bom odvzel bolezen.',
        26: '§ V tvoji deželi nič ne bo zavrglo svojih mladih niti ne bo jalovo. Število tvojih dni bom izpolnil.',
        27: 'Pred teboj bom poslal svoj strah in uničil bom vsa ljudstva, h katerim boš prišel in vsem tvojim sovražnikom bom storil, da svoje hrbte obrnejo k tebi.',
        28: 'Pred teboj bom poslal sršene, ki bodo izpred tebe napodili Hivéjce, Kánaance in Hetejce.',
        29: 'Izpred tebe jih ne bom pognal v enem letu, da ne bi zemlja postala zapuščena in bi se zoper tebe namnožile poljske zveri.',
        30: 'Po malo in malo jih bom podil izpred tebe, dokler ne boš narasel in podedoval dežele.',
        31: '§ Tvoje meje bom postavil od Rdečega morja, celo do morja Filistejcev in od puščave do reke, kajti jaz bom prebivalce dežele izročil v tvojo roko, ti pa jih boš pognal pred seboj.',
        32: 'Z njimi ne boš sklenil nobene zaveze niti z njihovimi bogovi.',
        33: 'Naj ne prebivajo v tvoji deželi, da te ne bi pripravili grešiti zoper mene, kajti če boš služil njihovim bogovom, ti bodo le-ti zagotovo zanka.«',
    },
    24: {
        1: 'Mojzesu je rekel: »Pridite gor h Gospodu, ti in Aron, Nadáb in Abihú ter sedemdeset Izraelovih starešin in obožujte daleč stran.«',
        2: 'Samo Mojzes pa bo prišel blizu Gospodu, toda oni naj ne pridejo blizu; niti ne bo ljudstvo z njim šlo gor.',
        3: 'Mojzes je prišel in ljudstvu povedal vse Gospodove besede in vse sodbe, in vse ljudstvo je odgovorilo z enim glasom ter reklo: »Vse besede, ki jih je povedal Gospod, bomo izpolnjevali.«',
        4: 'Mojzes je zapisal vse Gospodove besede in vstal zgodaj zjutraj in pod hribom zgradil oltar in dvanajst stebrov, glede na dvanajst Izraelovih rodov.',
        5: 'Poslal je mladeniče izmed Izraelovih otrok, ki so darovali žgalne daritve in žrtvovali mirovne daritve volov Gospodu.',
        6: 'Mojzes je vzel polovico od krvi ter jo dal v umivalnike, polovico od krvi pa je poškropil na oltar.',
        7: 'Vzel je knjigo zaveze in bral v občinstvu ljudstva, in rekli so: »Vse, kar je rekel Gospod, bomo izpolnjevali in bomo poslušni.«',
        8: 'Mojzes je vzel kri in jo poškropil na ljudstvo ter rekel: »Poglejte kri zaveze, ki jo je Gospod z vami sklenil glede vseh teh besed.«',
        9: 'Potem so šli gor Mojzes in Aron, Nadáb in Abihú ter sedemdeset izmed Izraelovih starešin,',
        10: 'in videli so Izraelovega Boga in pod njegovimi stopali je bilo kakor bi bilo to tlakovano delo iz kamna safirja in kakor bi bilo to nebeško telo v svoji jasnosti.',
        11: 'Na plemiče Izraelovih otrok pa ni položil svoje roke; tudi oni so videli Boga in so jedli ter pili.',
        12: 'Gospod je rekel Mojzesu: »Pridi gor k meni na goro in bodi tam, jaz pa ti bom dal kamniti plošči, postavo in zapovedi, ki sem jih zapisal, da jih boš lahko učil.«',
        13: 'Mojzes je vstal ter njegov strežnik Józue in Mojzes je šel gor na goro Boga.',
        14: 'Starešinam pa je rekel: »Čakajte tukaj na naju, dokler ponovno ne prideva k vam. Glejte, Aron in Hur sta z vami. Če ima katerikoli človek za urediti kakršnekoli zadeve, naj pride k njima.«',
        15: 'Mojzes je odšel gor na goro in goro je pokril oblak.',
        16: 'Gospodova slava je ostala na gori Sinaj in oblak jo je pokrival šest dni. Sedmi dan pa je iz srede oblaka zaklical k Mojzesu.',
        17: 'Prizor Gospodove slave na vrhu gore je bil v očeh Izraelovih otrok podoben požirajočemu ognju.',
        18: 'Mojzes je odšel v sredo oblaka in se povzpel na goro. Mojzes je bil na gori štirideset dni in štirideset noči.',
    },
    25: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Govori Izraelovim otrokom, da mi prinesejo daritev. Od vsakega človeka, ki to daje voljno, s svojim srcem, boste vzeli mojo daritev.',
        3: 'To je darovanje, ki ga boste jemali od njih: zlato, srebro, bron,',
        4: 'modro, vijolično, škrlatno in tanko laneno platno, kozjo dlako,',
        5: '§ rdeče barvane ovnove kože, jazbečeve kože, akacijev les,',
        6: 'olje za svetlobo, dišave za mazilno olje, za dišeče kadilo,',
        7: 'oniksove kamne in kamne, da bodo vdelani v efód in v naprsnik.',
        8: 'In naj mi naredijo svetišče, da bom lahko prebival med njimi.',
        9: 'Glede na vse, kar sem ti pokazal, po vzorcu šotorskega svetišča in vzorcu vseh njegovih priprav, celo tako boste to naredili.',
        10: 'Skrinjo bodo naredili iz akacijevega lesa. Dva komolca in pol bo njena dolžina, komolec in pol njena širina ter komolec in pol njena višina.',
        11: 'Prevlekel jo boš s čistim zlatom; znotraj in zunaj jo boš prevlekel in na njej naokoli boš naredil krono iz zlata.',
        12: 'Zanjo boš ulil štiri obroče iz zlata in jih namestil na njene štiri vogale. Dva obroča bosta na eni njeni strani, dva obroča pa na drugi njeni strani.',
        13: 'Naredil boš drogova iz akacijevega lesa in ju prevlekel z zlatom.',
        14: 'Drogova boš položil v obroča pri obeh straneh skrinje, da bo skrinja lahko z njima prenašana.',
        15: 'Drogova naj bosta v obročih skrinje. Naj ne bosta vzeta od nje.',
        16: 'V skrinjo pa boš položil pričevanje, ki ti ga bom dal.',
        17: 'Naredil boš sedež milosti iz čistega zlata. Dva komolca in pol naj bo njegova dolžina ter komolec in pol njegova širina.',
        18: 'Naredil boš dva keruba iz zlata, iz kovanega dela ju boš naredil, na dveh koncih sedeža milosti.',
        19: 'Enega keruba naredi na enem koncu, drugega keruba pa na drugem koncu. Iz sedeža milosti boš naredil keruba na dveh njegovih koncih.',
        20: 'Keruba naj svoji peruti iztegujeta na visoko, pokrivajoč sedež milosti s svojimi perutmi in njuna obraza naj gledata drug proti drugemu. Proti sedežu milosti naj bosta obraza kerubov.',
        21: 'Sedež milosti boš položil zgoraj nad skrinjo, v skrinjo pa boš položil pričevanje, ki ti ga bom dal.',
        22: 'Tam se bom srečeval s teboj in se iznad sedeža milosti posvetoval s teboj, izmed dveh kerubov, ki sta nad skrinjo pričevanja, izmed vseh stvari, ki jih bom dal tebi v zapoved Izraelovim otrokom.',
        23: 'Naredil boš tudi mizo iz akacijevega lesa. Dva komolca naj bo njena dolžina in komolec njena širina ter komolec in pol njena višina.',
        24: 'Prekril jo boš s čistim zlatom in k temu naokoli naredil krono iz zlata.',
        25: 'Naokoli ji boš naredil rob, za roko širok in k njenemu robu naokoli boš naredil zlato krono.',
        26: 'Zanjo boš naredil štiri zlate obroče iz zlata in obroče vstavil v štiri vogale, ki so na njenih štirih stopalih.',
        27: 'Nasproti robu bodo obroči za prostor drogovoma, za prenašanje mize.',
        28: 'Drogova boš naredil iz akacijevega lesa in ju prevlekel z zlatom, da bo z njima miza lahko prenašana.',
        29: '§ Naredil boš njene sklede in njene žlice in njene pokrove in njene skledice, da [jo] s tem pokriješ. Iz čistega zlata jih boš naredil.',
        30: 'Na mizi boš pred menoj nenehno postavljal hlebe navzočnosti.',
        31: 'Naredil boš svečnik iz čistega zlata. Iz kovanega dela bo svečnik narejen. Njegovo držalo, njegove veje, njegove skledice, njegovi popki in njegovi cvetovi bodo iz istega.',
        32: 'Šest vej naj izhaja iz njegovih strani; tri veje iz svečnika iz ene strani in tri veje iz svečnika iz druge strani;',
        33: '§ tri skledice, narejene podobne mandljem, s popkom in cvetom na eni veji; in tri skledice, narejene podobne mandljem, na drugi strani, s popkom in cvetom. Na takšen način na šestih vejah, ki izhajajo iz svečnika.',
        34: 'Na svečniku naj bodo štiri skledice narejene podobne mandljem, z njihovimi popki in njihovimi cvetovi.',
        35: 'Tam bo popek pod dvema vejama iz istega in popek pod dvema vejama iz istega in popek pod dvema vejama iz istega, glede na šest vej, ki izhajajo iz svečnika.',
        36: 'Njihovi popki in njihove veje bodo iz istega. Vse to bo eno kovano delo iz čistega zlata.',
        37: 'Naredil boš sedem njegovih svetilk in te bodo osvetljevale njegove svetilke, da mu bodo lahko nasproti dajale svetlobo.',
        38: 'Njegovi utrinjači in pladnji za utrinke naj bodo iz čistega zlata.',
        39: 'Iz talenta čistega zlata bo to naredil, z vsemi temi posodami.',
        40: 'Glej, da jih narediš po njihovem vzorcu, ki ti je bil pokazan na gori.',
    },
    26: {
        1: 'Poleg tega boš naredil šotorsko svetišče z desetimi zavesami iz sukane tančice in modre in vijolične in škrlatne. S kerubi spretne izdelave jih boš naredil.',
        2: 'Dolžina ene zavese naj bo osemindvajset komolcev in širina ene zavese štiri komolce. Vsaka izmed zaves bo imela eno mero.',
        3: 'Pet zaves bo spojeno skupaj druga k drugi, in drugih pet zaves bo spojenih skupaj druga k drugi.',
        4: 'Naredil boš zanke iz modrega na robu prve zavese od zarobitve v spoju, in enako boš storil na najbolj oddaljenem delu druge zavese, na spoju druge.',
        5: 'Petdeset zank boš naredil na eni zavesi in petdeset zank boš naredil na robu zavese, ki je na spoju druge, da bodo zanke lahko držale ena drugo.',
        6: 'Naredil boš petdeset zaponk iz zlata in zavese spojil skupaj z zaponkami, in to bo eno šotorsko svetišče.',
        7: 'Naredil boš zavese iz kozje dlake, da bodo pokrivalo nad šotorskim svetiščem. Enajst zaves boš naredil.',
        8: 'Dolžina ene zavese bo trideset komolcev in širina ene zavese štiri komolce. Vseh enajst zaves bo ene mere.',
        9: 'Pet zaves boš spojil posebej in šest zaves posebej in šesto zaveso boš prepognil v sprednjem delu šotorskega svetišča.',
        10: 'Naredil boš petdeset zank na robu prve zavese, ki je skrajna na spoju in petdeset zank na robu zavese, ki spaja drugo.',
        11: 'Naredil boš petdeset zaponk iz brona in zaponke položil v zanke in šotor spojil skupaj, da bo lahko eno.',
        12: 'Ostanek, ki preostane od šotorskih zaves, polovica zavese, ki preostaja, bo visela preko zadnje strani šotorskega svetišča.',
        13: 'Komolec na eni strani in komolec na drugi strani tega kar preostaja v dolžini zaves šotora, to bo viselo prek strani šotorskega svetišča na tej strani in na oni strani, da ga pokrije.',
        14: '§ Naredil boš pokrivalo za šotor iz rdeče barvanih ovnovih kož in gornje pokrivalo iz jazbečevih kož.',
        15: 'Naredil boš pokonci stoječe deske za šotorsko svetišče iz akacijevega lesa.',
        16: 'Deset komolcev naj bo dolžina deske, komolec in pol pa naj bo širina ene deske.',
        17: 'Dva zatiča naj bosta na eni deski, urejena v vrstnem redu, drug proti drugemu; tako boš naredil za vse deske šotorskega svetišča.',
        18: 'Naredil boš deske za šotorsko svetišče, dvajset desk na južni strani, proti jugu.',
        19: 'Pod dvajsetimi deskami boš naredil štirideset podstavkov iz srebra; dva podstavka pod eno desko za njena dva zatiča in dva podstavka pod drugo desko za njena dva zatiča.',
        20: 'Za drugo stran šotorskega svetišča, na severni strani, bo dvajset desk',
        21: 'in njihovih štirideset podstavkov iz srebra; dva podstavka pod eno desko in dva podstavka pod drugo desko.',
        22: 'Za strani šotorskega svetišča proti zahodu boš naredil šest desk.',
        23: 'Dve deski boš naredil za vogala šotorskega svetišča na dveh straneh.',
        24: 'Spodaj bosta spojeni skupaj in skupaj bosta spojeni nad glavo v en obroč. Tako bo to za oba; tako bosta za dva vogala.',
        25: 'Osem desk bo in njihovi podstavki iz srebra, šestnajst podstavkov; dva podstavka pod eno desko in dva podstavka pod drugo desko.',
        26: 'Naredil boš zapahe iz akacijevega lesa; pet za deske ene strani šotorskega svetišča',
        27: 'in pet zapahov za deske druge strani šotorskega svetišča in pet zapahov za deske strani šotorskega svetišča, za dve strani proti zahodu.',
        28: 'Srednji zapah v sredi desk naj sega od konca do konca.',
        29: 'Deske boš prevlekel z zlatom in njene obroče naredil iz zlata za prostore za zapahe in zapahe boš prevlekel z zlatom.',
        30: 'Vzdignil boš šotorsko svetišče glede na ta način, ki ti je bil pokazan na gori.',
        31: 'Naredil boš zagrinjalo iz modre, vijolične, škrlatne in sukane tančice spretne izdelave; s kerubi bo to narejeno.',
        32: 'Obesil jo boš na štiri stebre iz akacijevega lesa, prevlečene z zlatom. Njihovi kavlji bodo iz zlata, na štirih podstavkih iz srebra.',
        33: 'Zagrinjalo boš obesil pod zaponke, da boš lahko prinesel tja, znotraj zagrinjala, skrinjo pričevanja. Zagrinjalo vam bo razdelilo med svetim krajem in najsvetejšim.',
        34: 'Sedež milosti boš položil na skrinjo pričevanja v najsvetejšem kraju.',
        35: 'Mizo boš postavil zunaj zagrinjala in svečnik nasproti mizi na južni strani šotorskega svetišča in mizo boš postavil na severno stran.',
        36: 'Naredil boš tanko preprogo za vrata šotora iz modre, vijolične, škrlatne in sukane tančice, izdelane z vezenjem.',
        37: 'Za tanko preprogo boš naredil pet stebrov iz akacijevega lesa in jih prevlekel z zlatom in njihovi kavlji bodo iz zlata, in zanje boš ulil pet podstavkov iz brona.',
    },
    27: {
        1: 'Naredil boš oltar iz akacijevega lesa, pet komolcev dolg in pet komolcev širok. Oltar naj bo štirioglat. Njegova višina naj bo tri komolce.',
        2: 'Iz istega boš naredil rogove na njegovih štirih vogalih. Njegovi rogovi bodo iz istega, prekril pa ga boš z bronom.',
        3: 'Zanj boš naredil ponve, da sprejmejo pepel, lopate, umivalnike, kavlje za meso in ponve za žerjavico. Vse posode boš naredil iz brona.',
        4: 'Zanj boš naredil mrežasto rešetko iz brona in na mreži boš naredil štiri bronaste obroče na njenih štirih vogalih.',
        5: 'Položil jo boš spodaj, pod obod oltarja, da bo mreža lahko celo do srede oltarja.',
        6: 'Naredil boš drogova za oltar, drogova iz akacijevega lesa in ju prevlekel z bronom.',
        7: 'Drogova naj bosta vstavljena v obroče in drogova naj bosta na dveh straneh oltarja, da se ga nosi.',
        8: 'Votlega z deskami ga boš naredil; kakor ti je bilo pokazano na gori, tako naj ga napravijo.',
        9: 'Naredil boš dvor šotorskega svetišča; za južno stran, proti jugu, tam naj bodo tanke preproge za dvor iz sukane tančice, sto komolcev dolge za eno stran',
        10: 'in njenih dvajset stebrov in njihovih dvajset podstavkov naj bo iz brona. Kavlji stebrov in njihovi okrasni trakovi naj bodo iz srebra.',
        11: 'Podobno naj bodo za severno stran po dolžini tanke preproge, sto komolcev dolge in njegovih dvajset stebrov in njihovih dvajset podstavkov iz brona; kavlji stebrov in njihovi okrasni trakovi iz srebra.',
        12: 'Za širino dvora na zahodni strani naj bodo tanke preproge petdesetih komolcev; deset njihovih stebrov in deset njihovih podstavkov.',
        13: 'Širina dvora na vzhodni strani, proti vzhodu, naj bo petdeset komolcev.',
        14: 'Tanke preproge ene strani velikih vrat naj bo petnajst komolcev; trije njeni stebri in trije njihovi podstavki.',
        15: 'Na drugi strani naj bodo tanke preproge petnajstih komolcev. Trije njeni stebri in trije njihovi podstavki.',
        16: 'Za velika vrata dvora naj bo tanka preproga dvajsetih komolcev iz modre, vijolične, škrlatne in sukane tančice, izdelane z vezenjem; in njihovi stebri naj bodo štirje in štirje njihovi podstavki.',
        17: 'Vsi stebri okoli dvora naj bodo okrašeni s srebrom. Njihovi kavlji naj bodo iz srebra, njihovi podstavki pa iz brona.',
        18: 'Dolžina dvora naj bo sto komolcev in širina vsepovsod petdeset in višina pet komolcev iz sukane tančice, njihovi podstavki pa iz brona.',
        19: 'Vse posode šotorskega svetišča v vsej njegovi službi in vsi njegovi količki in vsi količki dvora, naj bodo iz brona.',
        20: 'Izraelovim otrokom pa boš zapovedal, da ti prinesejo čistega olja, iz stolčenih oliv, za svetlobo, da bi svetilka vedno gorela.',
        21: 'V šotorskem svetišču skupnosti, zunaj zagrinjala, ki je pred pričevanjem, jo bodo Aron in njegovi sinovi urejali od večera do jutra pred Gospodom. To naj bo zakon na veke njihovim rodovom v imenu Izraelovih otrok.',
    },
    28: {
        1: 'K sebi si vzemi svojega brata Arona in njegove sinove z njim, izmed Izraelovih otrok, da mi bo lahko služil v duhovniški službi, torej Arona, Nadába, Abihúja, Eleazarja in Itamárja, Aronove sinove.',
        2: 'Naredil boš sveta oblačila za svojega brata Arona, za slavo in za lepoto.',
        3: 'Govoril boš vsem, ki so modrega srca, ki sem jih napolnil z duhom modrosti, da bodo lahko naredili Aronove obleke, da ga posvetijo, da mi bo lahko služil v duhovniški službi.',
        4: 'To so obleke, ki jih bodo naredili: naprsnik, efód, svečano oblačilo in izvezen plašč, turban in pas. Naredili bodo sveta oblačila za tvojega brata Arona in njegove sinove, da mi bo lahko služil v duhovniški službi.',
        5: 'Vzeli bodo zlato, modro, vijolično, škrlatno in tanko laneno platno.',
        6: 'Naredili bodo efód iz zlata, iz modre in iz vijolične, iz škrlatne in sukane tančice s spretno izdelavo.',
        7: 'Ta bo imel dva svoja obramna dela spojena pri dveh njegovih robovih; in tako bo to spojeno skupaj.',
        8: 'Skrbno narejen pas efóda, ki je na njem, bo iz istega, glede na njegovo delo. Celo iz zlate, iz modre, vijolične, škrlatne in sukane tančice.',
        9: 'Vzel boš dva oniksova kamna in nanju vrezal imena Izraelovih otrok.',
        10: 'Šest izmed njihovih imen na en kamen in drugih šest imen preostalih na drug kamen, glede na njihovo rojstvo.',
        11: 'Z delom graverja v kamen, podobnemu gravuram pečata, boš dva kamna vgraviral z imeni Izraelovih otrok. Naredil ju boš, da bosta postavljena v ležišči iz zlata.',
        12: 'Dva kamna boš položil na ramena efóda za kamna spomina Izraelovim otrokom, in Aron bo njihova imena nosil pred Gospodom na svojih dveh ramenih v spomin.',
        13: 'Naredil boš ležišči iz zlata',
        14: 'in dve verižici iz čistega zlata na koncih; iz spletenega dela ju boš naredil in spletene verižice boš pritrdil k ležiščema.',
        15: 'Naprsnik sodbe boš naredil s spretno izdelavo; glede na delo efóda ga boš naredil; iz zlata, iz modre, iz vijolične, iz škrlatne in iz sukane tančice ga boš naredil.',
        16: 'Ta naj bo štirioglat, prepognjen. Pedenj naj bo njegova dolžina in pedenj naj bo njegova širina.',
        17: '§ Na njem boš postavil postavitev kamnov, torej štiri vrste kamnov. Prva vrsta naj bo sardij, topaz in granat. To naj bo prva vrsta.',
        18: '§ Druga vrsta naj bo smaragd, safir in diamant.',
        19: 'Tretja vrsta hijacint, ahat in ametist.',
        20: '§ Četrta vrsta beril, oniks in jaspis. Vstavljeni naj bodo v zlato v njihovih obdanostih.',
        21: 'Kamni naj bodo z imeni Izraelovih otrok, dvanajst, glede na njihova imena, podobno gravuram pečata; vsak s svojim imenom naj bodo glede na dvanajst rodov.',
        22: 'Na krajeh naprsnika boš naredil verižici iz spletenega dela, iz čistega zlata.',
        23: 'Na naprsniku boš naredil dva obročka iz zlata in dva obročka boš vstavil na dva konca naprsnika.',
        24: 'Dve spleteni verižici iz zlata boš vstavil v dva obročka, ki sta na krajeh naprsnika.',
        25: 'Druga dva konca dveh spletenih verižic boš pritrdil v dve ležišči in ju pripel na obramna dela efóda pred njim.',
        26: 'Naredil boš dva obročka iz zlata in ju položil na dva konca naprsnika v njegov rob, ki je na notranji strani efóda.',
        27: 'Naredil boš dva druga obročka iz zlata in ju položil na dve strani pod efód, proti njegovemu prednjemu [delu], nasproti drugemu njegovemu spoju, nad skrbno narejenim pasom efóda.',
        28: 'Naprsnik bodo z njegovimi obročki z modrim trakom privezali k obročkom efóda, da bo ta lahko nad skrbno narejenim pasom efóda in da naprsnik ne bo odvezan od efóda.',
        29: 'Aron naj nosi imena Izraelovih otrok na naprsniku sodbe, na svojem srcu, ko gre v sveti kraj, v nenehen spomin pred Gospodom.',
        30: 'Na naprsnik sodbe boš položil Urím in Tumím in ta dva bosta na Aronovem srcu, ko vstopa pred Gospoda in Aron naj sodbo Izraelovih otrok nenehno nosi na svojem srcu pred Gospodom.',
        31: 'Naredil boš svečano oblačilo efóda, celotno iz modrega.',
        32: 'Na vrhu le-tega naj bo luknja v njegovi sredi. Naj ima vezenje iz spletenega dela naokoli njegove luknje, kakor če bi bila luknja brezrokavne verižne srajce, da ta ne bo raztrgana.',
        33: 'Spodaj, na njegovem obšivu, boš naredil granatna jabolka iz modre in iz vijolične in iz škrlata, naokoli njegovega obšiva; in zvončke iz zlata naokoli med njimi.',
        34: 'Zlat zvonček in granatno jabolko, zlat zvonček in granatno jabolko, na obšivu naokoli svečanega oblačila.',
        35: 'In to naj bo na Aronu, da služi, in njegov zvok bo slišati, ko vstopa v sveti kraj pred Gospoda in ko prihaja ven, da ne umre.',
        36: 'Naredil boš tablico iz čistega zlata in nanjo vgraviral SVETO Gospodu, podobno gravuram pečata.',
        37: 'Položil jo boš na moder trak, da bo ta lahko na turbanu; ta bo na sprednjem delu turbana.',
        38: 'Ta bo na Aronovem čelu, da bo Aron lahko nosil krivičnost svetih stvari, ki jih bodo Izraelovi otroci posvečevali v vseh svojih svetih darilih, in ta naj bo vedno na njegovem čelu, da bodo lahko sprejeti pred Gospodom.',
        39: 'Izvezel boš plašč iz tankega lanenega platna in naredil boš turban iz tankega lanenega platna in naredil boš pas iz vezenine.',
        40: 'Za Aronove sinove boš naredil plašče in zanje boš naredil pasove in klobučke boš naredil zanje, za slavo in za lepoto.',
        41: 'Položil jih boš na svojega brata Arona in njegove sinove z njim. Mazilil jih boš in jih uméstil in posvétil, da mi bodo lahko služili v duhovniški službi.',
        42: 'Naredil jim boš kratke platnene hlače, da pokrijejo svojo nagoto. Segale bodo od ledij celo do stegna',
        43: 'in bodo na Aronu in na njegovih sinovih, ko pridejo v šotorsko svetišče skupnosti ali ko pridejo blizu k oltarju, da služijo na svetem kraju, da ne nosijo krivičnosti in ne umrejo. To naj bo za vedno zakon njemu in njegovemu semenu za njim.',
    },
    29: {
        1: 'To je stvar, ki jim jo boš storil, da jih posvetiš, da mi opravljajo službo duhovnika. Vzemi enega mladega bikca in dva ovna brez pomanjkljivosti,',
        2: 'nekvašen kruh in nekvašene kolače, umešane z oljem in nekvašene vaflje, pomazane z oljem; iz pšenične moke jih boš naredil.',
        3: 'Položil jih boš v eno košaro in prinesel v košari, z bikcem in dvema ovnoma.',
        4: 'Arona in njegove sinove boš privedel k vratom šotorskega svetišča skupnosti in jih umil z vodo.',
        5: 'Vzel boš obleke in na Arona nadel plašč, svečano oblačilo efóda, efód in naprsnik ter ga opasal s skrbno narejenim pasom efóda.',
        6: 'Na njegovo glavo boš položil turban in na turban boš položil sveto krono.',
        7: 'Potem boš vzel mazilno olje in ga izlil na njegovo glavo ter ga mazilil.',
        8: 'Privedel boš njegove sinove in nanje nadel plašče.',
        9: 'Opasal jih boš s pasovi, Arona in njegove sinove in nanje položil klobučke in duhovniška služba bo njihova po večnem zakonu, in uméstil boš Arona in njegove sinove.',
        10: 'Bikca boš dal privesti pred šotorsko svetišče skupnosti in Aron in njegovi sinovi bodo svoje roke položili bikcu na glavo.',
        11: 'Bikca boš zaklal pred Gospodom, pri vratih šotorskega svetišča skupnosti.',
        12: 'Vzel boš kri bikca in jo s svojim prstom pomazal na oltarne rogove in vso kri izlij poleg vznožja oltarja.',
        13: 'Vzel boš vso tolščo, ki pokriva drobovje, in opno, ki je nad jetri in dve ledvici in tolščo, ki je na njiju in jih sežgi na oltarju.',
        14: 'Toda meso bikca, njegovo kožo in njegov iztrebek boš zunaj tabora sežgal z ognjem. To je daritev za greh.',
        15: 'Vzel boš tudi enega ovna in Aron in njegovi sinovi bodo svoje roke položili na ovnovo glavo.',
        16: 'Zaklal boš ovna in vzel boš njegovo kri in jo poškropil naokoli nad oltarjem.',
        17: 'Ovna boš nasekal na kose in opral njegovo drobovje in njegove noge in jih položil k njegovim kosom in k njegovi glavi.',
        18: 'Vsega ovna boš sežgal na oltarju. To je žgalna daritev Gospodu. To je prijeten vonj, ognjena daritev Gospodu.',
        19: 'In vzel boš drugega ovna. Aron in njegovi sinovi bodo svoje roke položili na ovnovo glavo.',
        20: 'Potem boš ovna zaklal in vzel od njegove krvi in jo položil na konico Aronovega desnega ušesa in na konico desnega ušesa njegovih sinov in na palec njihove desne roke in na palec njihovega desnega stopala in kri boš poškropil naokoli po oltarju.',
        21: 'Vzel boš od krvi, ki je na oltarju in od mazilnega olja ter ga poškropil na Arona, na njegove obleke, na njegove sinove in na obleke njegovih sinov z njim, in posvečen bo on, njegove obleke, njegovi sinovi in z njim obleke njegovih sinov.',
        22: 'Od ovna boš vzel tudi tolščo, tolsti rep in tolščo, ki pokriva drobovje, opno nad jetri, dve ledvici in tolščo, ki je na njima in desno pleče, kajti to je oven uméstitve,',
        23: 'in en hleb kruha in en kolač oljnatega kruha in en vafelj iz košare nekvašenega kruha, ki je pred Gospodom.',
        24: 'Vse boš položil v Aronove roke in v roke njegovih sinov, in majal jih boš za majalno daritev pred Gospodom.',
        25: 'Sprejel jih boš iz njihovih rok in jih sežgal na oltarju za žgalno daritev, v prijeten vonj pred Gospodom. To je daritev, narejena z ognjem Gospodu.',
        26: 'Vzel boš prsi ovna Aronove uméstitve in to majal za majalno daritev pred Gospodom. To bo tvoj delež.',
        27: '§ Prsi majalne daritve in pleče vzdigovalne daritve, ki je majano in ki je vzdignjeno, boš posvétil, od ovna uméstitve, torej od tega, kar je za Arona in od tega kar je za njegove sinove.',
        28: 'To bo Aronovo in njegovih sinov od Izraelovih otrok po zakonu na veke, kajti to je vzdigovalna daritev. To bo vzdigovalna daritev od Izraelovih otrok, od darovanja njihovih mirovnih daritev, torej njihova vzdigovalna daritev Gospodu.',
        29: 'Aronova sveta oblačila bodo [pripadala] njegovim sinovom za njim, da bodo maziljeni v njih in da bodo uméščeni v njih.',
        30: 'In da jih bo ta sin, ki je namesto njega duhovnik, oblačil sedem dni, ko prihaja v šotorsko svetišče skupnosti, da služi na svetem kraju.',
        31: 'Vzel boš ovna uméstitve in na svetem kraju zavrel njegovo meso.',
        32: 'Aron in njegovi sinovi bodo jedli meso ovna in kruh, ki je v košari, pri vratih šotorskega svetišča skupnosti.',
        33: '§ Jedli bodo te stvari, s katerimi je narejena sprava, da jih uméstijo in posvétijo. Toda tujec ne bo jedel od tega, ker so svete.',
        34: 'Če bi karkoli, od mesa uméstitve ali od kruha, preostalo do jutra, potem boš preostanek sežgal z ognjem. To ne bo pojedeno, kajti to je sveto.',
        35: 'Tako boš storil Aronu in njegovim sinovim, glede na vse stvari, ki sem ti jih zapovedal. Sedem dni jih boš uméščal.',
        36: 'Vsak dan boš daroval bikca za spravo za daritev za greh in očistil boš oltar, ko si zanj opravil spravo in mazilil ga boš, da ga posvétiš.',
        37: 'Sedem dni boš delal spravo za oltar in ga posvečeval. To bo oltar najsvetejšega. Karkoli se dotakne oltarja, bo sveto.',
        38: 'Torej to je to, kar boš daroval na oltarju. Dve jagnjeti prvega leta, nenehno dan za dnem.',
        39: 'Eno jagnje boš daroval zjutraj, drugo jagnje pa boš daroval zvečer,',
        40: 'in z enim jagnjetom desetinko moke, pomešane s četrtinko vrča iztolčenega olja in četrtinko vrča vina za pitno daritev.',
        41: 'Drugo jagnje pa boš daroval zvečer in temu boš storil glede na jutranjo jedilno daritev in glede na to pitno daritev, za prijeten vonj, ognjena daritev Gospodu.',
        42: 'To bo skozi vaše rodove nenehna žgalna daritev pri vratih šotorskega svetišča skupnosti, pred Gospodom, kjer te bom srečal, da ti tam govorim.',
        43: 'Tam se bom srečal z Izraelovimi otroki in šotorsko svetišče bo posvečeno z mojo slavo.',
        44: 'Jaz bom šotorsko svetišče skupnosti in oltar posvétil, in jaz bom posvétil tako Arona, kakor njegove sinove, da mi služijo v duhovniški službi.',
        45: 'Jaz bom prebival med Izraelovi otroci in bom njihov Bog.',
        46: 'Spoznali bodo, da jaz sem Gospod, njihov Bog, ki jih je privedel ven iz egiptovske dežele, da lahko prebivam med njimi. Jaz sem Gospod, njihov Bog.',
    },
    30: {
        1: 'Naredil boš oltar, da na njem zažgeš kadilo. Iz akacijevega lesa ga boš naredil.',
        2: 'Komolec bo njegova dolžina in komolec njegova širina; ta bo štirioglat. Dva komolca bo njegova višina. Njegovi rogovi naj bodo iz istega.',
        3: 'Prevlekel ga boš s čistim zlatom, njegov vrh, njegove strani naokoli in njegove rogove in naokoli mu boš naredil krono iz zlata.',
        4: 'K njemu boš naredil dva zlata obroča pod njegovo krono, pri njegovih dveh vogalih, na njegovih dveh straneh boš to naredil. To bosta prostora za drogova, da ga z njima prenašajo.',
        5: 'Drogova boš naredil iz akacijevega lesa in ju prevlekel z zlatom.',
        6: 'Položil ga boš pred zagrinjalo, ki je pri skrinji pričevanja, pred sedež milosti, ki je nad pričevanjem, kjer se bom srečeval s teboj.',
        7: 'Aron bo na njem vsako jutro zažgal dišeče kadilo. Ko pripravlja svetilke, bo na njem zažgal kadilo.',
        8: 'Ko Aron zvečer prižge svetilke, bo na njem zažgal kadilo, neprestano kadilo pred Gospodom skozi vaše rodove.',
        9: 'Na njem ne boste darovali nobenega tujega kadila, niti žgalne daritve, niti jedilne daritve, niti nanj ne boste izlili pitne daritve.',
        10: 'Aron bo enkrat letno opravil spravo na njegovih rogovih, s krvjo spravnih daritev za greh. Enkrat letno bo na njem opravil spravo skozi vaše rodove. To je najsvetejše Gospodu.«',
        11: 'Gospod je spregovoril Mojzesu, rekoč:',
        12: '»Ko popišeš glave Izraelovih otrok, po njihovem številu, potem bodo dali, vsak človek, odkupnino za svojo dušo Gospodu, ko jih preštevaš; da med njimi ne bo nobene nadloge, ko jih ti preštevaš.',
        13: 'To bodo dali, vsak, kdor preide med tiste, ki so prešteti, polovico šekla po svetiščnem šeklu (šekel je dvajset ger); polovica šekla bo dar Gospodu.',
        14: 'Vsak, kdor preide med tiste, ki so prešteti, od dvajset let starih in navzgor, bo dal dar Gospodu.',
        15: 'Bogati ne bodo dali več in revni ne bodo dali manj kot polovico šekla, ko dajo dar Gospodu, da opravijo spravo za svoje duše.',
        16: 'Vzel boš spravni denar Izraelovih otrok in ga določil za službo šotorskega svetišča skupnosti, da bo to lahko spomin Izraelovim otrokom pred Gospodom, da opravijo spravo za vaše duše.«',
        17: 'Gospod je spregovoril Mojzesu, rekoč:',
        18: '»Naredil boš tudi [okrogel] bronast umivalnik in njegovo vznožje prav tako iz brona, da se s tem umivajo. To boš položil med šotorsko svetišče skupnosti in oltar in vanj boš dal vodo.',
        19: 'Kajti Aron in njegovi sinovi bodo tam umivali svoje roke in svoja stopala.',
        20: 'Ko gredo v šotorsko svetišče skupnosti, se bodo umili z vodo, da ne umrejo; ali ko pridejo blizu k oltarju, da služijo, da sežgejo ognjeno daritev Gospodu.',
        21: 'Tako bodo umivali svoje roke in svoja stopala, da ne umrejo. To bo zanje zakon na veke, torej njemu in njegovemu semenu skozi njihove rodove.«',
        22: 'Poleg tega je Gospod spregovoril Mojzesu, rekoč:',
        23: '»K sebi vzemi tudi glavne dišave, od čiste mire petsto šeklov, od prijetnega cimeta polovico toliko, torej dvesto petdeset šeklov, od sladkega kolmeža dvesto petdeset šeklov,',
        24: 'od kasije petsto šeklov, po svetiščnem šeklu in od olivnega olja vrč.',
        25: 'Naredil boš olje svetega mazila, mazilo zmešano po lekarnarski umetnosti. To bo sveto mazilno olje.',
        26: 'S tem boš mazilil šotorsko svetišče skupnosti, skrinjo pričevanja,',
        27: 'mizo in vse njene posode, svečnik in njegove posode, kadilni oltar,',
        28: 'oltar žgalne daritve z vsemi njegovimi posodami ter [okrogel] umivalnik in njegovo vznožje.',
        29: 'Posvétil jih boš, da bodo lahko najsvetejše. Karkoli se jih dotakne, bo sveto.',
        30: 'Mazilil boš Arona in njegove sinove in jih posvéti, da mi bodo lahko služili v duhovniški službi.',
        31: 'Izraelovim otrokom boš govoril, rekoč: ›To mi bo sveto mazilno olje skozi vaše rodove.‹',
        32: 'Na človeško meso naj ne bo izlito niti ne boste naredili kateregakoli drugega po njegovi sestavi podobnega temu. To je sveto in to vam bo sveto.',
        33: 'Kdorkoli zmeša karkoli podobnega temu, ali kdorkoli karkoli od tega položi na tujca, bo torej iztrebljen izmed svojega ljudstva.«',
        34: 'Gospod je rekel Mojzesu: »K sebi vzemi prijetne dišave, dišečo smolo, kadilno školjko in galban; te prijetne dišave s čistim kadilom. Od vsakega bo tam podobna teža.',
        35: 'Naredil boš dišavo, dišečino po lekarnarski umetnosti, umešano skupaj, čisto in sveto.',
        36: 'Nekaj od tega boš zelo drobno stolkel in to položil pred pričevanje v šotorskem svetišču skupnosti, kjer se bom srečeval s teboj. To ti bo najsvetejše.',
        37: 'Glede na dišavo, ki jo boš naredil, si jo sebi ne boste delali glede na njeno sestavo. Ta ti bo sveta za Gospoda.',
        38: 'Kdorkoli bo naredil podobno temu, da jo voha, bo torej iztrebljen izmed svojega ljudstva.«',
    },
    31: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Poglej, po imenu sem poklical Becaléla, Urijájevega sina, Hurovega sina, iz Judovega rodu.',
        3: 'Napolnil sem ga z Božjim duhom, v modrosti, v razumnosti, v znanju in v vseh vrstah rokodelstva,',
        4: 'da snuje spretna dela, da dela z zlatom, s srebrom, z bronom',
        5: 'in v rezanju kamnov, da se jih vdela in v rezbarjenju lesa, da dela v vseh vrstah rokodelstva.',
        6: 'Glej, jaz sem dal z njim Oholiába, Ahisamáhovega sina, iz Danovega rodu, in v srca vseh tistih, ki so modrega srca, sem položil modrost, da bodo lahko naredili vse to, kar sem ti zapovedal:',
        7: 'šotorsko svetišče skupnosti, skrinjo pričevanja, sedež milosti, ki je na njem, vso opremo šotorskega svetišča,',
        8: 'mizo in njeno opremo, čisti svečnik z vso njegovo opremo, kadilni oltar,',
        9: 'oltar žgalne daritve z vso njegovo opremo, [okrogel] umivalnik in njegovo vznožje,',
        10: 'službene obleke in sveta oblačila za duhovnika Arona in oblačila njegovih sinov, za služenje v duhovniški službi',
        11: 'ter mazilno olje in dišeče kadilo za sveti kraj. Storili bodo glede na vse to, kar sem ti zapovedal.«',
        12: 'Gospod je spregovoril Mojzesu, rekoč:',
        13: '»Govori tudi Izraelovim otrokom, rekoč; ›Resnično, ohranjali boste moje šabate, kajti to je znamenje med menoj in vami skozi vaše rodove, da boste vi lahko vedeli, da jaz sem Gospod, ki vas posvečujem.',
        14: 'Zato boste ohranjali šabat, kajti ta vam je svet. Vsak kdor ga omadežuje, ta bo zagotovo usmrčen, kajti kdorkoli v njem dela kakršnokoli delo, ta duša bo iztrebljena izmed svojega ljudstva.',
        15: 'Šest dni naj se opravlja delo, toda na sedmi je šabatni počitek, sveto Gospodu. Kdorkoli na šabatni dan počne kakršno koli delo, bo zagotovo usmrčen.',
        16: 'Zatorej bodo Izraelovi otroci ohranjali šabat, da šabat obeležujejo skozi njihove rodove za večno zavezo.',
        17: 'To je znamenje med menoj in Izraelovimi otroki na veke, kajti v šestih dneh je Gospod naredil nebo in zemljo in na sedmi dan je počival in bil osvežen.‹«',
        18: 'Mojzesu je dal, ko je z njim končal posvetovanje na gori Sinaj, dve plošči pričevanja, kamniti plošči, popisani z Božjim prstom.',
    },
    32: {
        1: 'Ko je ljudstvo videlo, da je Mojzes odlašal priti dol z gore, se je ljudstvo skupaj zbralo k Aronu in mu reklo: »Vstani, naredi nam bogove, ki bodo šli pred nami, kajti glede tega Mojzesa, človeka, ki nas je privedel iz egiptovske dežele, ne vemo kaj je nastalo iz njega.«',
        2: 'Aron jim je rekel: »Izdrite zlate uhane, ki so v ušesih vaših žena, vaših sinov in vaših hčera in jih prinesite k meni.«',
        3: 'Vse ljudstvo je izdrlo zlate uhane, ki so bili v njihovih ušesih in jih prineslo k Aronu.',
        4: 'Ta jih je prejel iz njihove roke in to oblikoval z rezbarskim orodjem, potem ko je naredil ulito tele, in rekli so: »To so tvoji bogovi, oh Izrael, ki so te privedli iz egiptovske dežele.«',
        5: 'Ko je Aron to videl, je pred njim zgradil oltar in Aron je naredil razglas ter rekel: »Jutri je praznovanje Gospodu.«',
        6: 'Naslednji dan so zgodaj vstali, darovali žgalne daritve in prinesli mirovne daritve in ljudstvo se je usedlo, da jé in da pije in vstalo, da se zabava.',
        7: 'Gospod je rekel Mojzesu: »Pojdi, stopi dol, kajti tvoje ljudstvo, ki si ga privedel iz egiptovske dežele, se je izpridilo.',
        8: 'Hitro so se obrnili stran iz poti, ki sem jim jo zapovedal. Naredili so si ulito tele, ga oboževali, mu žrtvovali in rekli: ›To so tvoji bogovi, oh Izrael, ki so te privedli gor iz egiptovske dežele.‹«',
        9: 'Gospod je rekel Mojzesu: »Videl sem to ljudstvo in glej, to je trdovratno ljudstvo.',
        10: 'Zdaj me torej pusti samega, da se moj bes razvname zoper njih in da jih lahko použijem. Iz tebe pa bom naredil velik narod.«',
        11: 'Mojzes je rotil Gospoda, svojega Boga in rekel: » Gospod, zakaj se tvoj bes razvnema zoper tvoje ljudstvo, ki si ga privedel iz egiptovske dežele z veliko močjo in z mogočno roko?',
        12: 'Zakaj bi Egipčani govorili in rekli: ›Zaradi zla jih je privedel ven, da jih ubije na gorah in da jih použije iz obličja zemlje?‹ Obrni se od svojega krutega besa in se pokesaj glede tega zla zoper svoje ljudstvo.',
        13: 'Spomni se Abrahama, Izaka in Izraela, svojih služabnikov, ki si jim prisegel pri samem sebi in jim rekel: ›Vaše seme bom pomnožil kakor zvezd neba in vso to deželo, o kateri sem govoril, bom dal tvojemu semenu in podedovali jo bodo na veke.‹«',
        14: 'Gospod se je pokesal glede zla, ki ga je mislil storiti svojemu ljudstvu.',
        15: 'Mojzes se je obrnil in odšel dol z gore in v njegovi roki sta bili dve plošči pričevanja. Plošči sta bili popisani na obeh njunih straneh; na eni strani in na drugi sta bili popisani.',
        16: 'Plošči sta bili Božje delo in pisanje je bilo pisanje od Boga, vgravirano na plošči.',
        17: 'Ko je Józue slišal hrup ljudstva, medtem ko so kričali, je Mojzesu rekel: » Tam, v taboru, je vojni hrup.«',
        18: 'Ta je rekel: » To ni glas tistih, ki vpijejo zaradi zmage niti to ni glas tistih, ki vpijejo, ker so bili premagani, temveč slišim hrup tistih, ki pojejo.«',
        19: 'Takoj ko je prišel blizu tabora, se je pripetilo, da je zagledal tele in ples. Mojzesova jeza se je vnela, tabli je vrgel iz svojih rok ter ju zlomil pod goro.',
        20: 'Vzel je tele, ki so ga naredili, ga sežgal v ognju, ga zmlel v prah in ga posul nad vodo in Izraelove otroke primoral, da so pili od tega.',
        21: 'Mojzes je Aronu rekel: »Kaj ti je storilo to ljudstvo, da si nadnje privedel tako velik greh?«',
        22: 'Aron je rekel: »Ne dopusti, da se razvname jeza mojega gospoda. Ti poznaš ljudstvo, da so postavljeni v zlo.',
        23: 'Kajti rekli so mi: ›Naredi nam bogove, ki bodo šli pred nami, kajti glede tega Mojzesa, človeka, ki nas je privedel iz egiptovske dežele, ne vemo kaj je nastalo iz njega.‹',
        24: 'Rekel sem jim: ›Kdorkoli ima kakršnokoli zlato, naj ga izdere.‹ Tako so ga dali meni. Potem sem ga vrgel v ogenj in izšlo je to tele.«',
        25: '§ Ko je Mojzes videl, da je bilo ljudstvo nago, (kajti Aron jih je storil nage v njihovo sramoto med njihovimi sovražniki)',
        26: 'potem je Mojzes stal v velikih vratih tabora in rekel: »Kdo je na Gospodovi strani? Naj pride k meni.« In k njemu so se zbrali vsi sinovi Lévijevcev.',
        27: 'Rekel jim je: »Tako govori Gospod, Izraelov Bog: ›Vsak mož naj svoj meč pripaše k svoji strani in gre noter in ven, od velikih vrat do velikih vrat, skozi tabor in naj vsak mož ubije svojega brata in vsak mož svojega družabnika in vsak mož svojega bližnjega.‹«',
        28: 'Otroci Lévijevcev so storili glede na Mojzesovo besedo in tam je ta dan izmed ljudstva padlo okoli tri tisoč mož.',
        29: 'Kajti Mojzes je rekel: »Uméstite se danes Gospodu, celo vsak mož za svojega sina in za svojega brata, da lahko ta dan nad vas podeli blagoslov.«',
        30: 'Naslednji dan se je pripetilo, da je Mojzes rekel ljudstvu: »Zagrešili ste velik greh. Sedaj bom šel gor h Gospodu, morda bom storil spravo za vaš greh.«',
        31: 'Mojzes se je vrnil h Gospodu ter rekel: »Oh, to ljudstvo je zagrešilo velik greh in si naredilo bogove iz zlata.',
        32: 'Vendar sedaj, če hočeš odpusti njihov greh ― in če ne, me izbriši, prosim te, iz svoje knjige, ki si jo napisal.«',
        33: 'Gospod je rekel Mojzesu: »Kdorkoli je grešil zoper mene, tistega bom izbrisal iz svoje knjige.',
        34: 'Zato sedaj pojdi, vodi ljudstvo na kraj, o katerem sem ti govoril. Glej, moj Angel bo šel pred teboj. Kljub temu bom na dan, ko obiščem, obiskal njihov greh na njih.«',
        35: 'Gospod je trpinčil ljudstvo, ker so naredili tele, ki ga je naredil Aron.',
    },
    33: {
        1: 'Gospod je rekel Mojzesu: »Odpravi se in pojdi od tod gor, ti in ljudstvo, ki si ga privedel gor iz egiptovske dežele, v deželo, ki sem jo prisegel Abrahamu, Izaku in Jakobu, rekoč: ›Tvojemu semenu jo bom dal,‹',
        2: 'jaz pa bom pred teboj poslal angela, in jaz bom napodil Kánaanca, Amoréjca in Hetejca in Perizéjca, Hivéjca in Jebusejca',
        3: 'v deželo, kjer tečeta mleko in med, kajti jaz ne bom šel gor v tvoji sredi, kajti trdovratno ljudstvo si, da te na poti ne použijem.«',
        4: 'Ko je ljudstvo slišalo te zle vesti, je žalovalo in noben človek si nase ni nadel ornamentov.',
        5: 'Kajti Gospod je rekel Mojzesu: »Reci Izraelovim otrokom: ›Vi ste trdovratno ljudstvo. V trenutku bom prišel v tvojo sredo in te použil, zato sedaj iz sebe odloži svoje ornamente, da lahko vem, kaj ti storiti.‹«',
        6: 'Izraelovi otroci so se pri gori Horeb ogolili svojih ornamentov.',
        7: 'Mojzes je vzel šotorsko svetišče in ga postavil zunaj tabora, daleč od tabora ter ga imenoval Šotorsko svetišče skupnosti. In pripetilo se je, da kdorkoli je iskal Gospoda, je odšel k šotorskemu svetišču skupnosti, ki je bil zunaj tabora.',
        8: 'Pripetilo se je, ko je Mojzes šel ven v šotorsko svetišče, da je vse ljudstvo vstalo in vsak mož je stal pri vratih svojega šotora in gledal za Mojzesom, dokler ta ni odšel v šotorsko svetišče.',
        9: 'Ko je Mojzes vstopil v šotorsko svetišče, se je pripetilo, [da] se je spustil oblačen steber in stal pri vratih šotorskega svetišča in Gospod je govoril z Mojzesom.',
        10: 'Vse ljudstvo je videlo oblačen steber stati pri vratih šotorskega svetišča, in vse ljudstvo je vstalo in oboževalo, vsak mož pri vratih svojega šotora.',
        11: 'Gospod je govoril Mojzesu iz obličja v obličje, kakor človek govori svojemu prijatelju. In ponovno se je napotil v tabor, toda njegov služabnik, Nunov sin Józue, mladenič, ni odšel iz šotorskega svetišča.',
        12: 'Mojzes je rekel Gospodu: »Glej, praviš mi: ›Privedi to ljudstvo gor,‹ pa mi nisi dal spoznati koga hočeš poslati z menoj. Vendar si rekel: ›Poznam te po imenu in tudi milost si našel v mojih očeh.‹',
        13: 'Zdaj torej, prosim te, če sem našel milost v tvojih očeh, pokaži mi torej svojo pot, da te lahko spoznam, da lahko najdem milost v tvojih očeh. Preudari, da je ta narod tvoje ljudstvo.«',
        14: 'In on je rekel: »Moja prisotnost bo šla s teboj in jaz ti bom dal počitek.«',
        15: 'Rekel mu je: »Če tvoja prisotnost ne gre z menoj, nas ne odvedi tja gor.',
        16: 'Kajti v čem bo to znano tukaj, da smo jaz in tvoje ljudstvo našli milost v tvojih očeh? Mar ni to v tem, da hodiš z nami? Tako bomo ločeni, jaz in tvoje ljudstvo, od vseh ljudstev, ki so na obličju zemlje.«',
        17: 'Gospod je rekel Mojzesu: »Storil bom tudi to stvar, ki si jo govoril, kajti našel si milost v mojih očeh in jaz te poznam po imenu.«',
        18: 'Ta je rekel: »Rotim te, pokaži mi svojo slavo.«',
        19: 'In on je rekel: »Vsej svoji dobroti bom storil iti pred teboj in razglašal bom Gospodovo ime pred teboj in milostljiv bom, komur hočem biti milostljiv in usmiljenje bom pokazal na tistem, na komer hočem pokazati usmiljenje.«',
        20: 'Rekel je: »Ne moreš videti mojega obličja, kajti noben človek me ne bo videl in živel.«',
        21: 'Gospod je rekel: »Glej, tukaj je prostor pri meni in ti boš stopil na skalo.',
        22: 'Zgodilo se bo, medtem ko gre moja slava mimo, da te bom postavil v skalno pečino in s svojo roko te bom pokril, medtem ko grem mimo.',
        23: 'In odstranil bom svojo roko in videl boš moje zadnje dele, toda mojega obličja ne bo videti.«',
    },
    34: {
        1: 'Gospod je rekel Mojzesu: »Izsekaj si dve kamniti plošči, podobni prvima, in na ti plošči bom napisal besede, ki so bile na prvih ploščah, ki si ju razbil.',
        2: 'Zjutraj bodi pripravljen in zjutraj pridi gor na goro Sinaj in se mi pokaži tam, na vrhu gore.',
        3: 'Noben človek ne bo prišel gor s teboj niti naj noben človek ne bo viden po vsej gori. Naj se niti tropi, niti črede ne pasejo pred to goro.«',
        4: 'In izklesal je dve kamniti plošči, podobni prvima dvema. Mojzes je vstal zgodaj zjutraj in odšel na goro Sinaj, kakor mu je zapovedal Gospod in v svojo roko vzel dve kamniti plošči.',
        5: 'Gospod se je spustil v oblaku in tam stal z njim in razglasil Gospodovo ime.',
        6: 'Gospod je šel mimo, pred njim in razglasil: » Gospod, Gospod Bog, usmiljen in milostljiv, potrpežljiv in obilen v dobroti in resnici,',
        7: 'ki ohranja usmiljenje za tisoče, ki odpušča krivičnost, prestopek in greh in ki nikakor ne bo očistil krivega; ki obiskuje krivičnost očetov na otrocih in na otrok otrocih, do tretjega in četrtega rodu.«',
        8: 'Mojzes se je podvizal in svojo glavo sklonil proti zemlji ter oboževal.',
        9: 'Rekel je: »Če sem torej našel milost v tvojih očeh, oh Gospod, naj moj Gospod, prosim te, hodi med nami, kajti to je trdovratno ljudstvo. Odpusti našo krivičnost in naš greh in nas vzemi za svojo dediščino.«',
        10: 'In on je rekel: »Glej, sklepam zavezo. Pred vsem tvojim ljudstvom bom delal čuda, kakršna še niso bila storjena po vsej zemlji niti v nobenem narodu. Vse ljudstvo, med katerim si, bo videlo Gospodovo delo, kajti to je strašna stvar, ki jo bom storil s teboj.',
        11: 'Obeležuj to, kar sem ti danes zapovedal. Glej, pred teboj napodim Amoréjca, Kánaanca, Hetejca, Perizéjca, Hivéjca in Jebusejca.',
        12: 'Pazi nase, da ne bi sklenil zaveze s prebivalci dežele, v katero greš, da ti ne bi bili za zanko v tvoji sredi,',
        13: 'temveč boste uničili njihove oltarje, zlomili njihove podobe in posekali njihove ašere,',
        14: 'kajti ne boš oboževal nobenega drugega boga, kajti Gospod, čigar ime je Ljubosumni, je ljubosumen Bog,',
        15: 'da ne bi sklenil zaveze s prebivalci dežele in bi se oni šli vlačugat s svojimi bogovi in bi žrtvovali svojim bogovom, in bi te nekdo povabil in bi ti jedel od njegove daritve,',
        16: 'in bi jemal od njihovih hčera za svoje sinove in bi se njihove hčere šle vlačugat za njihovimi bogovi in bi primoral svoje sinove, da se gredo vlačugat za njihovimi bogovi.',
        17: 'Sebi ne boš izdeloval nobenih ulitih bogov.',
        18: 'Obeleževal boš praznik nekvašenega kruha. Sedem dni boš jedel nekvašeni kruh, kot sem ti zapovedal, v času meseca abíba, kajti v mesecu abíbu si prišel iz Egipta.',
        19: 'Vse, kar odpre maternico, je moje. Vsak prvenec med tvojo živino, bodisi vol ali ovca, ki je samec.',
        20: 'Toda prvenca od osla boš odkupil z jagnjetom. Če pa ga ne odkupiš, potem mu boš zlomil tilnik. Odkupil boš vse prvorojeno izmed svojih sinov. In nihče se ne bo prazen prikazal pred menoj.',
        21: 'Šest dni boš delal, toda na sedmi dan boš počival; v času oranja in v času žetve boš počival.',
        22: 'Obeleževal boš praznovanje tednov, od prvih sadov pšenične žetve in praznovanja spravljanja ob koncu leta.',
        23: 'Trikrat na leto se bodo vsi vaši moški otroci prikazali pred Gospodom Bogom, Izraelovim Bogom.',
        24: 'Kajti jaz bom pred teboj pregnal narode in razširil tvoje meje. Niti si noben človek ne bo poželel tvoje dežele, kadar boš šel trikrat v letu gor, da se prikažeš pred Gospodom, svojim Bogom.',
        25: 'Krvi moje klavne daritve ne boš daroval s kvasom niti ne bo klavna daritev praznika pashe ostala do jutra.',
        26: 'Prvine od prvih sadov svoje zemlje boš prinesel v hišo Gospoda, svojega Boga. Kozlička ne boš kuhal v mleku njegove matere.«',
        27: 'Gospod je rekel Mojzesu: »Zapiši te besede, kajti po pomenu teh besed sem sklenil zavezo s teboj in z Izraelom.«',
        28: 'In tam je bil z Gospodom štirideset dni in štirideset noči; niti ni jedel kruha niti pil vode. In na tabli je zapisal besede te zaveze, deset zapovedi.',
        29: 'Pripetilo se je, ko je Mojzes prišel dol z gore Sinaj, z dvema ploščama pričevanja v Mojzesovi roki, ko je prišel dol z gore, da Mojzes ni vedel, da je koža njegovega obraza sijala, medtem ko je govoril z njim.',
        30: 'Ko so Aron in vsi Izraelovi otroci zagledali Mojzesa, glej, koža njegovega obraza je sijala in so se bali priti bliže k njemu.',
        31: 'Mojzes jim je zaklical in Aron in vsi voditelji skupnosti so se vrnili k njemu, in Mojzes je govoril z njimi.',
        32: 'Potem so vsi Izraelovi otroci prišli bliže in v zapoved jim je dal vse, kar je Gospod govoril z njim na gori Sinaj.',
        33: 'Ko je Mojzes prenehal govoriti z njimi, si je na obraz dal zagrinjalo.',
        34: 'Toda ko je Mojzes vstopil pred Gospoda, da govori z njim, je odstranil zagrinjalo, dokler ni prišel ven. In prišel je ven in govoril Izraelovim otrokom to, kar mu je bilo zapovedano.',
        35: 'Izraelovi otroci so videli Mojzesov obraz, da je Mojzesova koža sijala in Mojzes si je na svoj obraz ponovno namestil zagrinjalo, dokler ni vstopil, da govori z njim.',
    },
    35: {
        1: 'Mojzes je zbral skupaj vso skupnost Izraelovih otrok ter jim rekel: »To so besede, ki jih je Gospod zapovedal, da naj bi jih vi delali.',
        2: 'Šest dni naj bo delo opravljano, toda na sedmi dan naj vam bo sveti dan, šabatni počitek Gospodu. Kdorkoli v njem opravlja delo, bo usmrčen.',
        3: 'Vsepovsod po svojih prebivališčih na šabatni dan ne boste prižigali nobenega ognja.«',
        4: 'Mojzes je spregovoril vsej skupnosti Izraelovih otrok, rekoč: »To je stvar, ki jo je zapovedal Gospod, rekoč:',
        5: '›Vzemite izmed vas daritev Gospodu. Kdorkoli je voljnega srca, naj jo prinese, daritev Gospodu: zlato, srebro, bron,',
        6: 'modro, vijolično, škrlatno in tanko laneno platno, kozjo dlako,',
        7: '§ rdeče barvane ovnove kože, jazbečeve kože, akacijev les,',
        8: 'olje za svetlobo, dišave za mazilno olje in za dišeče kadilo,',
        9: 'oniksove kamne in kamne, da se pripravijo za efód in za naprsnik.',
        10: 'Vsak, ki je izmed vas modrega srca, bo prišel in storil vse, kar je Gospod zapovedal:',
        11: 'šotorsko svetišče, njegov šotor in njegovo pokrivalo, njegove zaponke in njegove deske, njegove zapahe, njegove stebre in njegove podstavke,',
        12: 'skrinjo in njena drogova s sedežem milosti in zagrinjalo pokrivala,',
        13: 'mizo in njena drogova, vse njene posode in hlebe navzočnosti,',
        14: 'tudi svečnik za svetlobo in njegovo opremo in njegove svetilke z oljem za svetlobo',
        15: 'in kadilni oltar in njegova drogova, mazilno olje in dišeče kadilo, tanko preprogo za vrata pri šotorskem vhodu šotorskega svetišča,',
        16: 'oltar žgalne daritve z njegovo bronasto rešetko, njegova drogova in vse njegove posode, [okrogel] umivalnik in njegovo vznožje,',
        17: 'tanke preproge dvora, njegove stebre in njihove podstavke in tanko preprogo za vrata dvora,',
        18: 'količke šotorskega svetišča, količke dvora in njihove vrvice,',
        19: 'službene obleke, da opravljajo službo na svetem kraju, sveta oblačila za duhovnika Arona in oblačila njegovih sinov, za služenje v duhovniški službi.‹«',
        20: 'Vsa skupnost Izraelovih otrok je odšla iz Mojzesove prisotnosti.',
        21: 'Prišli so, vsakdo, čigar srce ga je razvnelo in vsakdo, čigar duh ga je storil voljnega in prinesli so Gospodovo daritev h gradnji šotorskega svetišča skupnosti in za vso njegovo službo in za sveta oblačila.',
        22: 'Prišli so, tako moški kakor ženske, tako veliko kot jih je bilo voljnega srca in prinesli zapestnice, uhane, prstane, ogrlice, vse dragocenosti iz zlata. Vsak človek, ki je daroval, je daroval daritev zlata Gospodu.',
        23: '§ Vsak človek, pri katerem je bilo najdeno modro, vijolično, škrlatno in tanko laneno platno, kozja dlaka, rdeča koža ovnov in jazbečeve kože, jih je prinesel.',
        24: 'Vsak, kdor je daroval daritev srebra in brona, je prinesel Gospodovo daritev. Vsak človek, pri komer se je našel akacijev les za katerokoli delo službe, ga je prinesel.',
        25: 'Vse ženske, ki so bile modrega srca, so predle s svojimi rokami in prinesle to, kar so napredle, tako iz modrega, iz vijoličnega in iz škrlata in iz tankega lanenega platna.',
        26: 'Vse ženske, ki jih je srce razvnelo v modrosti, so predle kozjo dlako.',
        27: 'Voditelji so prinesli oniksove kamne in kamne, da se pripravijo za efód in za naprsnik,',
        28: 'dišavo in olje za svetlobo in za mazilno olje in za dišeče kadilo.',
        29: 'Izraelovi otroci so prinesli voljno daritev Gospodu, vsak moški in ženska, katerega srce jih je storilo voljne, da prinesejo za vse vrste dela, ki ga je Gospod zapovedal, da bo storjeno po Mojzesovi roki.',
        30: 'Mojzes je Izraelovim otrokom rekel: »Glejte, Gospod je po imenu poklical Becaléla, Urijájevega sina, Hurovega sina, iz Judovega rodu',
        31: 'in ga napolnil z Božjim duhom, v modrosti, v razumevanju, v znanju in v vseh vrstah rokodelstva',
        32: 'in da snuje nenavadna dela, da dela v zlatu, v srebru, v bronu,',
        33: 'v rezanju kamnov, da se jih vdela in v rezbarjenju lesa, da naredi vsake vrste spretno delo.',
        34: 'V njegovo srce je položil, da lahko poučuje, tako on in Oholiáb, Ahisamáhov sin, iz Danovega rodu.',
        35: 'Napolnil ju je s srčno modrostjo, da opravljata vse vrste dela, od graverja do spretnega delavca in od tistega, ki izveze v modri, v vijolični, v škrlatni in v tankem lanenem platnu do tkalca, celó izmed teh, ki opravljajo katerokoli delo in izmed teh, ki snujejo spretno delo.«',
    },
    36: {
        1: 'Potem so Becalél in Oholiáb in vsak človek modrega srca, v katerega je Gospod položil modrost in razumevanje, da ve, kako delati vse vrste dela za službo svetišča, izvršili glede na vse, kakor je zapovedal Gospod.',
        2: 'Mojzes je poklical Becaléla in Oholiába in vsakega človeka modrega srca, v katerega srce je Gospod položil modrost, torej vsakega, ki ga je razvnelo srce, da pride k delu, da ga opravi',
        3: 'in od Mojzesa so prejeli vso daritev, ki so jo Izraelovi otroci prinesli za delo službe svetišča, da to istočasno opravijo. In k njemu so še vsako jutro prinašali prostovoljne daritve.',
        4: 'Prišli so vsi modri možje, ki so opravljali delo pri svetišču, vsak človek od svojega dela, ki so ga opravljali',
        5: 'in spregovorili Mojzesu, rekoč: »Ljudstvo prinaša veliko več kakor dovolj za delo služenja, ki ga je Gospod zapovedal narediti.«',
        6: 'Mojzes je dal zapoved in naredili so, da je bila razglašena po taboru, rekoč: »Naj niti moški niti ženska ne opravlja več nobenega dela za darovanje svetišču.« Tako je bilo ljudstvo zadržano od prinašanja.',
        7: 'Kajti stvari, ki so jih imeli, je bilo zadosti za izvršitev vsega dela in še preveč.',
        8: 'Vsak človek modrega srca med njimi, ki opravlja delo šotorskega svetišča, je naredil deset zaves iz sukane tančice, modre, vijolične in škrlatne. S kerubi spretne izdelave jih je naredil.',
        9: 'Dolžina ene zavese je bila osemindvajset komolcev in širina ene zavese štiri komolce. Zavese so bile vse ene velikosti.',
        10: 'Spojil je pet zaves eno k drugi in drugih pet zaves je spojil eno k drugi.',
        11: 'Naredil je zanke iz modre na robu prve zavese od zarobitve v spoju. Podobno je naredil na zadnji strani druge zavese na spoju druge.',
        12: 'Petdeset zank je naredil na eni zavesi in petdeset zank je naredil na robu zavese, ki je bila na spoju druge. Zanke so eno zaveso držale k drugi.',
        13: 'Naredil je petdeset zaponk iz zlata in zavese spojil z zaponkami skupaj eno k drugi. Tako je postalo eno šotorsko svetišče.',
        14: 'Naredil je zavese iz kozje dlake za šotor nad šotorskim svetiščem. Naredil je enajst zaves.',
        15: 'Dolžina ene zavese je bila trideset komolcev in štiri komolce je bila širina ene zavese. Enajst zaves je bilo ene velikosti.',
        16: 'Spojil je pet zaves posebej in šest zaves posebej.',
        17: 'Naredil je petdeset zank na zadnjem robu zavese na spoju in petdeset zank je naredil na robu zavese, ki spaja drugo.',
        18: 'Naredil je petdeset zaponk iz brona, da šotor spoji skupaj, da bo ta lahko eno.',
        19: 'Naredil je pokrivalo za šotor iz rdeče barvanih ovnovih kož in nad tem pokrivalo iz jazbečevih kož.',
        20: 'Naredil je deske za šotorsko svetišče iz akacijevega lesa, stoječe pokonci.',
        21: 'Dolžina deske je bila deset komolcev in širina deske en komolec in pol.',
        22: 'Ena deska je imela dva zatiča, enako oddaljena eden od drugega. Tako je naredil za vse deske šotorskega svetišča.',
        23: 'Naredil je deske za šotorsko svetišče; dvajset desk za južno stran, proti jugu.',
        24: 'Pod dvajsetimi deskami je naredil štirideset podstavkov iz srebra; dva podstavka pod eno desko za njena dva zatiča in dva podstavka pod drugo desko za njena dva zatiča.',
        25: 'Za drugo stran šotorskega svetišča, ki je proti severnemu vogalu, je naredil dvajset desk',
        26: 'in njihovih štirideset podstavkov iz srebra; dva podstavka pod eno desko in dva podstavka pod drugo desko.',
        27: 'Za strani šotorskega svetišča proti zahodu je naredil šest desk.',
        28: 'Dve deski je naredil za vogala šotorskega svetišča na dveh straneh.',
        29: 'Spojeni sta bili spodaj in skupaj spojeni pri njegovi glavi v en obroč. Tako je storil obema izmed njiju na obeh vogalih.',
        30: 'Bilo je osem desk in njihovih podstavkov je bilo šestnajst podstavkov iz srebra, pod vsako desko dva podstavka.',
        31: 'Naredil je zapahe iz akacijevega lesa; pet za deske ene strani šotorskega svetišča',
        32: 'in pet zapahov za deske druge strani šotorskega svetišča in pet zapahov za deske šotorskega svetišča proti zahodu.',
        33: 'Naredil je srednji zapah, da je segal skozi deske od enega konca k drugemu.',
        34: 'Deske je prevlekel z zlatom in njihove obroče naredil iz zlata, da bodo postavljeni za zapahe in zapahe je prevlekel z zlatom.',
        35: 'Naredil je zagrinjalo iz modre, vijolične, škrlatne in sukane tančice. S kerubi spretne izdelave jih je naredil.',
        36: 'K temu je naredil štiri stebre iz akacijevega lesa in jih prevlekel z zlatom. Njihovi kavlji so bili iz zlata in zanje je ulil štiri podstavke iz srebra.',
        37: 'Naredil je tanko preprogo za vrata šotorskega svetišča iz modre, vijolične, škrlatne in sukane tančice, iz vezenine;',
        38: 'in njenih pet stebrov z njihovimi kavlji. Njihove kapitele in njihove okrasne trakove je prevlekel z zlatom, toda njihovih pet podstavkov je bilo iz brona.',
    },
    37: {
        1: 'Becalél je naredil skrinjo iz akacijevega lesa. Dva komolca in pol je bila njena dolžina, komolec in pol njena širina, komolec in pol njena višina,',
        2: 'in jo zunaj in znotraj prevlekel s čistim zlatom in ji naokoli naredil krono iz zlata.',
        3: '§ Zanjo je ulil štiri obroče iz zlata, da bi bili vstavljeni pri njenih štirih vogalih; celo dva obroča na eni njeni strani in dva obroča na drugi njeni strani.',
        4: 'Naredil je drogova iz akacijevega lesa in ju prevlekel z zlatom.',
        5: 'Drogova je položil v obroča pri straneh skrinje, za prenašanje skrinje.',
        6: 'Naredil je sedež milosti iz čistega zlata. Dva komolca in pol je bila njegova dolžina ter komolec in pol njegova širina.',
        7: 'Naredil je dva keruba iz zlata, naredil ju je skovana iz enega kosa, na dveh koncih sedeža milosti;',
        8: 'enega keruba na koncu, na tej strani in drugega keruba na drugem koncu, na tisti strani. Iznad sedeža milosti je naredil keruba na dveh njegovih koncih.',
        9: 'Keruba sta svoji peruti razprostirala navzgor in s svojimi perutmi pokrivala nad sedežem milosti, s svojima obrazoma drug proti drugemu; torej k sedežu milosti sta bila obraza kerubov.',
        10: 'Naredil je mizo iz akacijevega lesa. Dva komolca je bila njena dolžina, komolec njena širina ter komolec in pol njena višina.',
        11: 'Prevlekel jo je s čistim zlatom in k temu naokoli naredil krono iz zlata.',
        12: 'K temu je naokoli naredil tudi okvir za širino dlani in naredil krono iz zlata za njen okvir naokoli.',
        13: 'Zanjo je ulil štiri obroče iz zlata in jih dal na njene štiri vogale, ki so bili na njenih štirih nogah.',
        14: 'Nasproti okvira so bili obroči, prostori za drogova, za prenašanje mize.',
        15: 'Naredil je drogova iz akacijevega lesa in ju prevlekel z zlatom, za prenašanje mize.',
        16: 'Naredil je posode, ki so bile na mizi, njene sklede, njene žlice, njene skledice in njena pokrivala, da jo z njimi pokrije, iz čistega zlata.',
        17: 'Naredil je svečnik iz čistega zlata. Iz kovanega dela je naredil svečnik; njegovo držalo in njegovo vejo, njegove skledice, njegove popke in njegove rože so bile iz istega.',
        18: 'In šest mladik, ki so izhajale iz njegovih strani; tri mladike iz svečnika iz ene njegove strani in tri mladike iz svečnika iz druge njegove strani.',
        19: 'Tri skledice je naredil po videzu mandljev iz ene mladike, popek in rožo in tri skledice je naredil podobne mandljem na drugi mladiki, popek in rožo. Tako povsod po šestih mladikah, ki izhajajo iz svečnika.',
        20: 'Na svečniku so bile štiri skledice narejene podobne mandljem, njegovim popkom in njegovim cvetovom;',
        21: 'popek pod dvema mladikama iz istega in popek pod dvema mladikama iz istega in popek pod dvema mladikama iz istega, glede na šest mladik, izhajajočih iz njega.',
        22: 'Njihovi popki in njihove veje so bile iz istega. Vse to je bilo eno kovano delo iz čistega zlata.',
        23: 'Naredil je njegovih sedem svetilk in njegova utrinjala in njegove pladnje za utrinjala iz čistega zlata.',
        24: 'Iz talenta čistega zlata ga je naredil in vse njegove posode.',
        25: 'Naredil je kadilni oltar iz akacijevega lesa. Njegova dolžina je bila komolec in njegova širina komolec; bil je štirioglat in dva komolca je bila njegova višina; njegovi rogovi so bili iz istega.',
        26: 'Prevlekel ga je s čistim zlatom, tako njegovo površino kot njegove strani naokoli in njegove rogove. Naokoli mu je naredil tudi krono iz zlata.',
        27: 'Zanj je naredil dva obroča iz zlata pod njegovo krono, pri njegovih dveh vogalih, na njegovih straneh, da bodo prostori za drogova, da ga z njima prenašajo.',
        28: 'Naredil je drogova iz akacijevega lesa in ju prevlekel z zlatom.',
        29: 'Naredil je sveto mazilno olje in čisto kadilo iz prijetnih dišav, glede na lekarnarjevo delo.',
    },
    38: {
        1: 'Naredil je oltar žgalne daritve iz akacijevega lesa. Pet komolcev je bila njegova dolžina in pet komolcev njegova širina; bil je štirioglat in tri komolce je bila njegova višina.',
        2: 'Naredil je njegove rogove na njegovih štirih vogalih; njegovi rogovi so bili iz istega, in prevlekel jih je z bronom.',
        3: 'Naredil je vse oltarne posode, lonce, lopate, umivalnike in kavlje za meso in ponve za žerjavico. Vse njegove posode je naredil iz brona.',
        4: 'Za oltar je naredil bronasto mrežasto rešetko pod njegovim obodom, spodaj, v njegovi sredi.',
        5: 'Ulil je štiri obroče za štiri konce bronaste rešetke, da bodo prostori za drogova.',
        6: 'Naredil je drogova iz akacijevega lesa in ju prevlekel z bronom.',
        7: 'Drogova je položil v obroče na straneh oltarja, da ga z njima prenašajo; oltar je naredil votel, z deskami.',
        8: 'Naredil je [okrogel] bronast umivalnik in njegovo vznožje iz brona, iz zrcal ženskega zbora, ki so se zbirale pri vratih šotorskega svetišča skupnosti.',
        9: 'Naredil je dvor. Na južni strani, proti jugu, so bile tanke preproge dvora iz sukane tančice, sto komolcev.',
        10: 'Njihovih stebrov je bilo dvajset in dvajset njihovih bronastih podstavkov; kavlji stebrov in njihovi okrasni trakovi so bili iz srebra.',
        11: 'Za severno stran je bilo tankih preprog sto komolcev, njihovih stebrov je bilo dvajset in dvajset njihovih podstavkov iz brona; kavlji stebrov in njihovi okrasni trakovi iz srebra.',
        12: 'Za zahodno stran so bile tanke preproge petdesetih komolcev, deset njihovih stebrov in deset njihovih podstavkov; kavlji stebrov in njihovi okrasni trakovi iz srebra.',
        13: 'Za vzhodno stran, proti vzhodu, petdeset komolcev.',
        14: 'Tankih preprog ene strani velikih vrat je bilo petnajst komolcev; njihovi trije stebri in njihovi trije podstavki.',
        15: 'In za drugo stran velikih vrat dvora, na tej roki in tisti roki, so bile tanke preproge petnajstih komolcev; trije njihovi stebri in trije njihovi podstavki.',
        16: 'Vse tanke preproge dvora naokoli so bile iz sukane tančice.',
        17: 'Podstavki za stebre so bili iz brona; kavlji stebrov in njihovi okrasni trakovi iz srebra in prevleka njihovih kapitelov iz srebra; in vsi stebri dvora so bili okrašeni s srebrom.',
        18: 'Tanka preproga za velika dvorna vrata je bilo vezenje iz modre, vijolične, škrlatne in sukane tančice. Dvajset komolcev je bila dolžina in pet komolcev je bilo visoko po širini, primerljivo tankim preprogam dvora.',
        19: 'Njihovi stebri so bili štirje in štirje njihovi podstavki iz brona; njihovi kavlji iz srebra in prevleka njihovih kapitelov in njihovih okrasnih trakov iz srebra.',
        20: 'Vsi količki šotorskega svetišča in dvora naokoli so bili iz brona.',
        21: 'To je seštevek šotorskega svetišča, torej šotorskega svetišča pričevanja, kakor je bilo prešteto glede na Mojzesovo zapoved, za službo Lévijevcev, po roki Itamárja, sina duhovnika Arona.',
        22: 'In Becalél, Urijájev sin, Hurov sin, iz Judovega rodu, je naredil vse, kar je Gospod zapovedal Mojzesu.',
        23: 'Z njim je bil Oholiáb, Ahisamáhov sin, iz Danovega rodu, graver, spreten delavec in vezalec v modri, vijolični, škrlatni in tankem lanenem platnu.',
        24: 'Vsega zlata, ki je bilo vključeno za delo v vsem delu svetega kraja, celo darovanega zlata, je bilo devetindvajset talentov in sedemsto trideset šeklov, po svetiščnem šeklu.',
        25: 'Srebra od tistih, ki so bili prešteti izmed skupnosti, je bilo sto talentov in tisoč sedemsto petinsedemdeset šeklov, po svetiščnem šeklu.',
        26: 'Pol šekla za vsakega človeka, to je polovica šekla, po svetiščnem šeklu, za vsakogar, ki je odšel, da bi bil preštet, od dvajsetih let starosti in naprej, za šeststo tri tisoč petsto petdeset mož.',
        27: 'Iz stotih talentov srebra so bili uliti podstavki svetišča in podstavki zagrinjala; sto podstavkov iz sto talentov, talent za podstavek.',
        28: 'Iz tisoč sedemsto petinsedemdesetih šeklov je naredil kavlje za stebre in prevlekel njihove kapitele ter jih okrasil.',
        29: 'Darovanega brona je bilo sedemdeset talentov in dva tisoč štiristo šeklov.',
        30: 'In s tem je naredil podstavke k vratom šotorskega svetišča skupnosti, bronast oltar in zanj bronasto rešetko, vse oltarne posode,',
        31: 'podstavke dvora naokoli in podstavke velikih vrat dvora in vse količke šotorskega svetišča in vse količke dvora naokoli.',
    },
    39: {
        1: 'Iz modre, vijolične in škrlatne so naredili službene obleke, da opravljajo službo na svetem kraju in naredijo sveta oblačila za Arona; kakor je Gospod zapovedal Mojzesu.',
        2: 'Naredil je efód iz zlate, modre, vijolične, škrlatne in sukane tančice.',
        3: 'Zlato so prekovali v tanke plošče in ga narezali v žice, da bi ga vdelali v modro, v vijolično, v škrlatno in v tanko laneno platno, s spretno izdelavo.',
        4: 'Za to so naredili obramna dela, da to spojijo skupaj; z dvema robovoma je bilo to spojeno skupaj.',
        5: 'Skrbno narejen pas njegovega efóda, ki je bil na njem, je bil iz istega, glede na njegovo delo; iz zlate, modre, vijolične, škrlatne in sukane tančice; kakor je Gospod zapovedal Mojzesu.',
        6: 'Izdelali so oniksova kamna, obdana z ležiščema iz zlata, vgravirana kakor so vgravirani pečati, z imeni Izraelovih otrok.',
        7: 'Položil jih je na ramena efóda, da bodo kamni za spomin Izraelovim otrokom; kakor je Gospod zapovedal Mojzesu.',
        8: 'Naredil je naprsnik spretne izdelave, podoben efódovemu delu; iz zlate, modre, vijolične, škrlatne in sukane tančice.',
        9: 'Bil je štirioglat; naprsnik so naredili prepognjen. Pedenj je bila njegova dolžina in pedenj njegova širina; bil je prepognjen.',
        10: 'Na njem so postavili štiri vrste kamnov. Prva vrsta je bil sardij, topaz in granat. To je bila prva vrsta.',
        11: 'Druga vrsta smaragd, safir in diamant.',
        12: 'Tretja vrsta hijacint, ahat in ametist.',
        13: 'Četrta vrsta beril, oniks in jaspis; bili so obdani v ležišča iz zlata v njihovih obdanostih.',
        14: 'Kamni so bili glede na imena Izraelovih otrok, dvanajst, glede na njihova imena, podobni gravuram pečata, vsak s svojim imenom, glede na dvanajst rodov.',
        15: 'Na naprsniku so naredili verižici na krajih, iz spletenega dela, iz čistega zlata.',
        16: 'Naredili so dve ležišči iz zlata in dva zlata obročka in dva zlata obročka vstavili v dva konca naprsnika.',
        17: 'Vstavili so dve spleteni verižici iz zlata v dva obročka, na krajeh naprsnika.',
        18: 'Dva konca dveh spletenih verižic so privezali na dve ležišči in ju pritrdili na obramna dela efóda, pred njim.',
        19: 'Naredili so dva obročka iz zlata in ju položili na dva konca naprsnika, na njegov rob, ki je bil na notranji strani efóda.',
        20: 'Naredili so dva druga zlata obročka in ju položili na dve strani pod efód, proti njegovi prednji strani, nasproti drugemu njegovemu spoju, nad skrbno narejenim pasom efóda.',
        21: 'Naprsnik z njegovimi obročki so z modrim trakom privezali k obročkom efóda, da bi bil ta lahko nad skrbno narejenim pasom efóda in da se naprsnik ne bi odvezal od efóda; kakor je Gospod zapovedal Mojzesu.',
        22: 'Naredil je svečano oblačilo efóda iz spletenega dela, celega iz modre.',
        23: 'Bila je luknja v sredi svečanega oblačila, kakor luknja brezrokavne verižne srajce s trakom naokoli luknje, da se ne raztrga.',
        24: 'Na obšivih svečanega oblačila so naredili granatna jabolka iz modre, vijolične, škrlatne in sukane tančice.',
        25: 'Naredili so zvončke iz čistega zlata in zvončke postavili med granatna jabolka, na obšivu svečanega oblačila, naokoli med granatnimi jabolki;',
        26: 'zvonček in granatno jabolko, zvonček in granatno jabolko naokoli obšiva svečanega oblačila za služenje v tem; kakor je Gospod zapovedal Mojzesu.',
        27: 'Naredili so plašče iz tankega lanenega platna iz spletenega dela, za Arona in za njegove sinove',
        28: 'in turban iz tankega lanenega platna in čedne klobučke iz tankega lanenega platna in kratke platnene hlače iz sukane tančice',
        29: 'in pas iz sukane tančice in modre in vijolične in škrlatne, iz vezenine; kakor je Gospod zapovedal Mojzesu.',
        30: 'Naredili so ploščico svete krone iz čistega zlata in nanjo napisali pisanje, podobno gravuram pečata: »SVETO Gospodu.«',
        31: 'K temu so privezali moder trak, da ga pričvrstijo visoko na turbanu; kakor je Gospod zapovedal Mojzesu.',
        32: 'Tako je bilo vse delo šotorskega svetišča skupnosti končano. Izraelovi otroci so storili glede na vse, kar je Gospod zapovedal Mojzesu, tako so storili.',
        33: 'Šotorsko svetišče so prinesli k Mojzesu, šotor, vso njegovo opremo, njegove zaponke, njegove deske, njegove zapahe, njegove stebre, njegove podstavke,',
        34: 'pokrivalo rdeče barvanih ovnovih kož, pokrivalo iz jazbečevih kož, zagrinjalo pokrivala,',
        35: 'skrinjo pričevanja, njena drogova, sedež milosti,',
        36: 'mizo in vse njene posode in hlebe navzočnosti,',
        37: 'čisti svečnik z njegovimi svetilkami, celo s svetilkami, da so razvrščene in vse njegove posode in olje za svetlobo,',
        38: 'zlat oltar, mazilno olje in dišeče kadilo, tanko preprogo za vrata šotorskega svetišča,',
        39: 'bronast oltar, njegovo rešetko iz brona, njegova drogova in vse njegove posode, [okrogel] umivalnik in njegovo vznožje,',
        40: 'tanko preprogo dvora, njegove stebre in njegove podstavke, tanko preprogo za velika dvorna vrata, njene vrvice in njene količke in vse posode službe šotorskega svetišča za shodni šotor,',
        41: 'službene obleke, da opravljajo službo na svetem kraju in sveta oblačila za duhovnika Arona in oblačila njegovih sinov, za služenje v duhovniški službi.',
        42: 'Glede na vse, kar je Gospod zapovedal Mojzesu, tako so Izraelovi otroci opravili vse delo.',
        43: 'Mojzes je pogledal na vse delo in glej, naredili so ga kakor je Gospod zapovedal, celo tako so ga naredili, in Mojzes jih je blagoslovil.',
    },
    40: {
        1: 'Gospod je spregovoril Mojzesu, rekoč:',
        2: '»Na prvi dan prvega meseca boš postavil šotorsko svetišče skupnosti.',
        3: 'Vanj boš postavil skrinjo pričevanja in skrinjo pokril z zagrinjalom.',
        4: 'Prinesel boš mizo in uredil stvari, ki naj bi bile razvrščene na njej, in vanj boš prinesel svečnik ter prižgal njegove svetilke.',
        5: 'Postavil boš oltar iz zlata za kadilo pred skrinjo pričevanja in k vratom šotorskega svetišča obesil tanko preprogo.',
        6: 'Postavil boš oltar žgalne daritve pred vrati šotorskega svetišča shodnega šotora.',
        7: '[Okrogel] umivalnik boš postavil med shodni šotor in oltar in vanj boš dal vodo.',
        8: 'Napravil boš dvor naokoli in pri velikih vratih dvora obesil tanko preprogo.',
        9: 'Vzel boš mazilno olje in mazilil šotorsko svetišče in vse, kar je v njem in ga posvetil in vse njegove posode in to bo sveto.',
        10: 'Mazilil boš oltar žgalne daritve in vse njegove posode in oltar posvéti. To bo oltar, najsvetejše.',
        11: 'Mazilil boš [okrogel] umivalnik in njegovo vznožje in ga posvétil.',
        12: 'Arona in njegove sinove boš privedel k vratom šotorskega svetišča skupnosti in jih umil z vodo.',
        13: 'Na Arona boš nadel sveta oblačila in mazili ga in posvéti ga, da mi bo lahko služil v duhovniški službi«.',
        14: 'Privedel boš njegove sinove in jih oblekel s plašči.',
        15: 'Mazilil jih boš, kakor si mazilil njihovega očeta, da mi bodo lahko služili v duhovniški službi, kajti njihovo maziljenje bo zagotovo večno duhovništvo skozi njihove rodove.«',
        16: 'Tako je Mojzes storil. Glede na vse, kar mu je Gospod zapovedal, tako je storil.',
        17: 'Pripetilo se je v prvem mesecu, v drugem letu, na prvi dan meseca, da je bilo šotorsko svetišče vzdignjeno.',
        18: 'Mojzes je vzdignil šotorsko svetišče, privezal njegove podstavke, postavil njegove deske, vstavil njegove zapahe in vzdignil njegove stebre.',
        19: 'In šotor je razprostrl nad šotorskim svetiščem, in nad njim postavil pokrivalo šotora; kakor je Gospod zapovedal Mojzesu.',
        20: 'Vzel je pričevanje, ga položil v skrinjo, drogova namestil na skrinjo in na skrinjo položil sedež milosti.',
        21: 'Skrinjo je prinesel v šotorsko svetišče in obesil zagrinjalo pokrivala ter pokril skrinjo pričevanja; kakor je Gospod zapovedal Mojzesu.',
        22: 'Mizo je položil v shodni šotor, proti severni strani šotorskega svetišča, zunaj zagrinjala.',
        23: 'Na njej je urejeno položil kruh pred Gospodom; kakor je Gospod zapovedal Mojzesu.',
        24: 'Svečnik je postavil v shodni šotor, nasproti mizi, na strani šotorskega svetišča proti jugu.',
        25: 'Pred Gospodom je prižgal svetilke; kakor je Gospod zapovedal Mojzesu.',
        26: 'Zlati oltar je postavil v shodnem šotoru pred zagrinjalom',
        27: 'in na njem je zažgal dišeče kadilo; kakor je Gospod zapovedal Mojzesu.',
        28: 'Pri vratih šotorskega svetišča je obesil tanko preprogo.',
        29: 'Pri vratih šotorskega svetišča shodnega šotora je postavil oltar žgalne daritve in na njem daroval žgalno daritev in jedilno daritev; kakor je Gospod zapovedal Mojzesu.',
        30: 'Med shodni šotor in oltar je postavil [okrogel] umivalnik in vanj dal vodo, da se z njo umiva.',
        31: 'Mojzes, Aron in njegovi sinovi so tam umivali svoje roke in svoja stopala.',
        32: 'Ko so odhajali v shodni šotor in ko so prihajali bliže k oltarju, so se umili; kakor je Gospod zapovedal Mojzesu.',
        33: 'Dvor je uredil naokoli šotorskega svetišča in oltarja in obesil tanko preprogo velikih dvornih vrat. Tako je Mojzes končal delo.',
        34: 'Potem je oblak pokril shodni šotor in Gospodova slava je napolnila šotorsko svetišče.',
        35: 'Mojzes pa ni bil zmožen vstopiti v shodni šotor, ker je na njem vztrajal oblak in Gospodova slava je napolnila šotorsko svetišče.',
        36: 'Ko je bil oblak dvignjen iznad šotorskega svetišča, so Izraelovi otroci odšli naprej po vseh svojih poteh,',
        37: 'toda če oblak ni bil dvignjen, potem niso potovali do dneva, ko je bil dvignjen gor.',
        38: 'Kajti Gospodov oblak je bil nad šotorskim svetiščem podnevi, ogenj pa je bil na njem ponoči, v očeh vse Izraelove hiše, na vseh njihovih poteh.',
    },
}
